#!/opt/onshape_oauth/bin/python3
"""
Onshape OAuth Callback Server
"""

from flask import Flask, request, jsonify
import os
import secrets
import base64
import hashlib

app = Flask(__name__)

# Store for auth code
auth_code_store = {}
tokens_store = {}

@app.route('/callback')
def callback():
    """Handle OAuth callback from Onshape"""
    code = request.args.get('code')
    state = request.args.get('state')
    error = request.args.get('error')

    if error:
        return f"<h1>OAuth Error</h1><p>{error}</p><p>You can close this window.</p>", 400

    if code:
        # Store the auth code temporarily
        auth_code_store['code'] = code
        auth_code_store['state'] = state

        return f"""
        <h1>Authorization Successful!</h1>
        <p>Code: {code[:20]}...</p>
        <p>State: {state}</p>
        <p>You can close this window now.</p>
        <script>setTimeout(() => window.close(), 3000);</script>
        """

    return "<h1>No code received</h1>", 400

@app.route('/get_code')
def get_code():
    """API endpoint to retrieve stored auth code"""
    code = auth_code_store.get('code')
    state = auth_code_store.get('state')
    if code:
        return jsonify({
            'code': code,
            'state': state,
            'status': 'success'
        })
    return jsonify({'status': 'pending'}), 202

@app.route('/get_tokens')
def get_tokens():
    """API endpoint to retrieve stored tokens"""
    tokens = tokens_store.get('tokens')
    if tokens:
        return jsonify({
            'access_token': tokens.get('access_token'),
            'refresh_token': tokens.get('refresh_token'),
            'expires_at': tokens_store.get('expires_at'),
            'status': 'success'
        })
    return jsonify({'status': 'pending'}), 202

@app.route('/tokens', methods=['POST'])
def set_tokens():
    """Store tokens from token exchange"""
    data = request.get_json()
    if data:
        tokens_store['tokens'] = {
            'access_token': data.get('access_token'),
            'refresh_token': data.get('refresh_token'),
            'expires_in': data.get('expires_in')
        }
        tokens_store['expires_at'] = data.get('expires_in', 3600)
        return jsonify({'status': 'stored'})
    return jsonify({'status': 'error'}), 400

@app.route('/health')
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    # Run on port 8000
    app.run(host='0.0.0.0', port=8000, debug=False)

