function createVentSlots(body, wallLength, wallHeight, slotWidth, slotCount, side) {
  // side: 'intake' (bottom) or 'exhaust' (top)
  const slotLength = wallLength / (slotCount * 2 + 1);
  const yPos = (side === 'intake') ? 5 : wallHeight - 5 - slotWidth/2;
  for (let i = 0; i < slotCount; i++) {
    const xPos = slotLength * (i * 2 + 0.5);
    const slot = forgecad.operations.rounded_rectangle(slotLength * 0.7, slotWidth, 1);
    slot.translate(xPos, yPos, 0);
    body = forgecad.operations.bool_difference(body, slot);
  }
  return body;
}

function createM3CountersunkHole(parent, x, y, z, depth) {
  const tap = forgecad.primitives.cylinder(params.m3TapDia.value / 2, depth);
  const sink = forgecad.primitives.cylinder(params.m3CountersinkDia.value / 2, 2);
  sink.translate(0, 0, -2);
  const hole = forgecad.operations.fuse(tap, sink);
  hole.translate(x, y, z);
  return forgecad.operations.cut(parent, hole);
}

function createInterlockTab(x, y, z, tabW, tabH, tabD, dir) {
  // dir: 1 = positive X, -1 = negative X, 2 = positive Y, -2 = negative Y
  const tab = forgecad.primitives.box(tabW, tabH, tabD);
  let tx = x, ty = y, tz = z;
  if (dir === 1) tx += tabW / 2;
  else if (dir === -1) tx -= tabW / 2;
  else if (dir === 2) ty += tabH / 2;
  else if (dir === -2) ty -= tabH / 2;
  tab.translate(tx, ty, tz);
  return tab;
}

function addInterlockTabsToWall(wall, wallLength, wallHeight, wallThick, tabW, tabD) {
  // Add tabs on sides for interlocking with adjacent walls
  // Top and bottom edges get tabs
  const tabH = wallHeight;
  // Left side tab (protruding left)
  const leftTab = forgecad.primitives.box(tabW, tabH, wallThick);
  leftTab.translate(-tabW/2 + 0.1, wallHeight/2, wallThick/2);
  wall = forgecad.operations.fuse(wall, leftTab);
  // Right side slot (indentation) — simulated by building wall slightly wider
  const rightTab = forgecad.primitives.box(tabW, tabH, wallThick);
  rightTab.translate(wallLength + tabW/2 - 0.1, wallHeight/2, wallThick/2);
  wall = forgecad.operations.fuse(wall, rightTab);
  return wall;
}

