// AI API Configuration for Nutrition App

const CONFIG_KEY = 'nutrition_ai_config';

export const DEFAULT_CONFIG = {
  apiKey: '',
  baseUrl: 'https://api.openai.com/v1',
  model: 'gpt-4o-mini',
  temperature: 0.7,
  maxTokens: 1000,
};

export const getConfig = () => {
  try {
    const saved = localStorage.getItem(CONFIG_KEY);
    if (saved) {
      return { ...DEFAULT_CONFIG, ...JSON.parse(saved) };
    }
  } catch (e) {
    console.warn('Failed to load AI config:', e);
  }
  return { ...DEFAULT_CONFIG };
};

export const saveConfig = (config) => {
  localStorage.setItem(CONFIG_KEY, JSON.stringify(config));
};

export const isConfigured = () => {
  const config = getConfig();
  return Boolean(config.apiKey && config.baseUrl);
};

// AI Integration for Nutrition App
// Uses OpenAI-compatible API format

import { getConfig, isConfigured } from './config';
import { db } from './db';
import { calculateBMR, calculateTDEE, calculateTargetCalories, calculateMacros, getTodayString } from './nutrition';

// System prompt for nutrition AI assistant
const SYSTEM_PROMPT = `Ты — опытный нутрициолог и консультант по питанию. Твоя задача — помогать пользователю вести дневник питания и давать полезные советы.

Отвечай на русском языке кратко и по делу.

Ты можешь:
1. Анализировать описанные блюда и оценивать их питательную ценность
2. Предлагать замены для более здорового питания
3. Давать советы по достижению целей (похудение, набор массы, поддержание)
4. Парсить названия блюд и оценивать их калорийность

Формат ответа —-friendly, не список, а живой разговор.

Когда пользователь описывает еду, можешь упомянуть примерную калорийность и БЖУ.

Если нужно задать уточняющий вопрос — спрашивай коротко.`;

/**
 * Send a message to the AI and get a response
 * @param {string} message - User message
 * @param {Array} history - Previous conversation history [{role, content}]
 * @returns {Promise<{text: string, error?: string}>}
 */
export async function askAI(message, history = []) {
  const config = getConfig();

  if (!isConfigured()) {
    return {
      text: '',
      error: 'AI не настроен. Укажите API-ключ в настройках.',
    };
  }

  try {
    const messages = [
      { role: 'system', content: SYSTEM_PROMPT },
      ...history,
      { role: 'user', content: message },
    ];

    const response = await fetch(`${config.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.apiKey}`,
      },
      body: JSON.stringify({
        model: config.model,
        messages,
        temperature: config.temperature,
        max_tokens: config.maxTokens,
      }),
    });

    if (!response.ok) {
      const errData = await response.json().catch(() => ({}));
      const errMsg = errData.error?.message || `HTTP ${response.status}`;
      return { text: '', error: `Ошибка API: ${errMsg}` };
    }

    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || '';

    return { text, error: null };
  } catch (err) {
    return {
      text: '',
      error: `Сетевая ошибка: ${err.message}`,
    };
  }
}

