- Осталось: ${Math.round(remaining.calories)} ккал
- Белки: ${Math.round(todayTotals.protein)}/${targets.protein}г (осталось ${Math.round(remaining.protein)}г)
- Жиры: ${Math.round(todayTotals.fat)}/${targets.fat}г (осталось ${Math.round(remaining.fat)}г)
- Углеводы: ${Math.round(todayTotals.carbs)}/${targets.carbs}г (осталось ${Math.round(remaining.carbs)}г)
- Цель: ${profile?.goal || 'maintain'}

Пользователь описывает приём пищи:
"${description}"

Проведи анализ и дай краткую оценку.`;

  if (!isConfigured()) {
    return {
      analysis: 'Укажите API-ключ для AI-анализа в настройках.',
      meals: [],
      error: 'not_configured',
    };
  }

  try {
    const messages = [
      { role: 'system', content: SYSTEM_PROMPT },
      { role: 'user', content: contextPrompt },
    ];

    const response = await fetch(`${config.baseUrl}/chat/completions`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${config.apiKey}`,
      },
      body: JSON.stringify({
        model: config.model,
        messages,
        temperature: 0.7,
        max_tokens: 800,
      }),
    });

    if (!response.ok) {
      const errData = await response.json().catch(() => ({}));
      return {
        analysis: '',
        meals: [],
        error: errData.error?.message || `HTTP ${response.status}`,
      };
    }

    const data = await response.json();
    const text = data.choices?.[0]?.message?.content || '';

    return { analysis: text, meals: [], error: null };
  } catch (err) {
    return {
      analysis: '',
      meals: [],
      error: `Сетевая ошибка: ${err.message}`,
    };
  }
}

