// Recommendations Screen - AI-powered meal suggestions based on remaining daily budget
import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Bot, Loader, RefreshCw, Coffee, Utensils } from 'lucide-react';
import { getRecommendations } from '../utils/ai';
import { db } from '../utils/db';
