import { mealTypes } from '../data/defaultData';

export default function RecommendationsScreen() {
  const navigate = useNavigate();
  const [recommendations, setRecommendations] = useState('');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [lastUpdated, setLastUpdated] = useState(null);

  const profile = db.getProfile();
  const today = getTodayString();
  const todayMeals = db.getMealsByDate(today);

  // Calculate today's progress
  const todayTotals = todayMeals.reduce((acc, m) => ({
    protein: acc.protein + (m.protein || 0),
    fat: acc.fat + (m.fat || 0),
    carbs: acc.carbs + (m.carbs || 0),
    calories: acc.calories + (m.calories || 0),
  }), { protein: 0, fat: 0, carbs: 0, calories: 0 });

  let targets = { calories: 2000, protein: 150, fat: 65, carbs: 250 };
  if (profile) {
    const bmr = calculateBMR(profile.weight, profile.height, profile.age, profile.sex);
    const tdee = calculateTDEE(bmr, profile.activityLevel);
    const targetCals = calculateTargetCalories(tdee, profile.goal);
    const macros = calculateMacros(targetCals, profile.goal, profile.activityLevel);
    targets = { calories: targetCals, ...macros };
  }

  const remaining = {
    calories: Math.max(0, targets.calories - todayTotals.calories),
    protein: Math.max(0, targets.protein - todayTotals.protein),
    fat: Math.max(0, targets.fat - todayTotals.fat),
    carbs: Math.max(0, targets.carbs - todayTotals.carbs),
  };

  const calPercent = Math.round((todayTotals.calories / targets.calories) * 100);
  const isOver = todayTotals.calories > targets.calories;

  const fetchRecommendations = async () => {
    setLoading(true);
    setError(null);

    const result = await getRecommendations();

    setLoading(false);

    if (result.error) {
      setError(result.error === 'not_configured' 
        ? 'Укажите API-ключ в настройках профиля' 
        : `Ошибка: ${result.error}`);
    } else {
      setRecommendations(result.recommendations);
      setLastUpdated(new Date());
    }
  };

  useEffect(() => {
    fetchRecommendations();
  }, []);

  return (
    <div className="screen">
      <header className="header">
        <button className="icon-btn" onClick={() => navigate(-1)}>
          <ArrowLeft size={24} />
        </button>
        <div className="header-title-row">
          <Bot size={24} className="header-icon" />
          <h1>Рекомендации</h1>
        </div>
        <button className="icon-btn" onClick={fetchRecommendations} disabled={loading}>
          <RefreshCw size={20} className={loading ? 'spin' : ''} />
        </button>
      </header>

      <div className="recommendations-container">
        {/* Remaining Budget Card */}
        <div className="budget-card">
          <div className="budget-header">
            <span className="budget-label">Осталось на сегодня</span>
            <span className={`budget-status ${isOver ? 'over' : 'ok'}`}>
              {isOver ? 'Перебор +' : 'В рамках'}
            </span>
          </div>

          <div className="budget-main">
            <span className={`budget-calories ${isOver ? 'over' : ''}`}>
              {isOver ? '+' : ''}{formatCalories(Math.abs(remaining.calories))}
            </span>
            <span className="budget-unit">ккал</span>
          </div>

          <div className="budget-macros">
            <div className="budget-macro">
              <span className="macro-label">Б</span>
              <span className="macro-val">{Math.round(remaining.protein)}г</span>
            </div>
            <div className="budget-macro">
              <span className="macro-label">Ж</span>
              <span className="macro-val">{Math.round(remaining.fat)}г</span>
            </div>
            <div className="budget-macro">
              <span className="macro-label">У</span>
              <span className="macro-val">{Math.round(remaining.carbs)}г</span>
            </div>
          </div>

          <div className="budget-progress">
            <div className="budget-progress-bar">
              <div 
                className={`budget-progress-fill ${isOver ? 'over' : ''}`}
                style={{ width: `${Math.min(calPercent, 100)}%` }}
              />
            </div>
            <span className="budget-progress-text">{calPercent}% дневной нормы</span>
          </div>
        </div>

        {/* Today's Meals Summary */}
        <div className="today-meals-summary">
          <h3>Сегодня съедено</h3>
          <div className="meals-summary-list">
            {mealTypes.map(type => {
              const typeMeals = todayMeals.filter(m => m.mealType === type.id);
              const typeCal = typeMeals.reduce((a, m) => a + (m.calories || 0), 0);
              return (
                <div key={type.id} className="meal-summary-row">
                  <span className="meal-summary-name">{type.name}</span>
                  <span className="meal-summary-cal">{typeCal > 0 ? `${typeCal} ккал` : '—'}</span>
                </div>
              );
            })}
          </div>
        </div>

        {/* AI Recommendations */}
        <div className="ai-recommendations">
          <div className="rec-header">
            <Bot size={20} />
            <h3>Что поесть?</h3>
          </div>

          {loading ? (
            <div className="rec-loading">
              <Loader size={20} className="spin" />
              <span>Думаю...</span>
            </div>
          ) : error ? (
            <div className="rec-error">
              <p>{error}</p>
              <button onClick={() => navigate('/profile')} className="rec-action-btn">
                Настройки профиля
              </button>
            </div>
          ) : (
            <div className="rec-content">
              <div className="rec-text">
                {recommendations.split('\n').map((line, i) => (
                  line.trim() && <p key={i}>{line.trim()}</p>
                ))}
              </div>
              {lastUpdated && (
                <span className="rec-updated">
                  Обновлено {lastUpdated.toLocaleTimeString('ru-RU', { hour: '2-digit', minute: '2-digit' })}
                </span>
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

// CameraScreen - Photo capture + AI recognition + manual correction
import { useState, useRef, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
