import { askAI, parseMealFromAI } from '../utils/ai';
import { db } from '../utils/db';
import { getTodayString, mealTypes } from '../data/defaultData';

export default function CameraScreen() {
  const navigate = useNavigate();
  const videoRef = useRef(null);
  const canvasRef = useRef(null);

  const [hasCamera, setHasCamera] = useState(false);
  const [capturedImage, setCapturedImage] = useState(null);
  const [analyzing, setAnalyzing] = useState(false);
  const [aiResponse, setAiResponse] = useState(null);
  const [editingMeal, setEditingMeal] = useState(null);
  const [mealType, setMealType] = useState('breakfast');
  const [quantity, setQuantity] = useState(1);
  const [error, setError] = useState(null);

  useEffect(() => {
    startCamera();
    return () => {
      if (videoRef.current && videoRef.current.srcObject) {
        videoRef.current.srcObject.getTracks().forEach(t => t.stop());
      }
    };
  }, []);

  const startCamera = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'environment' }
      });
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        setHasCamera(true);
      }
    } catch (err) {
      console.warn('Camera not available:', err);
      setHasCamera(false);
      setError('Камера недоступна. Вы можете ввести данные вручную.');
    }
  };

  const capturePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;

    canvas.width = video.videoWidth;
    canvas.height = video.videoHeight;
    const ctx = canvas.getContext('2d');
    ctx.drawImage(video, 0, 0);

    const dataUrl = canvas.toDataURL('image/jpeg', 0.8);
    setCapturedImage(dataUrl);

    // Stop camera
    if (video.srcObject) {
      video.srcObject.getTracks().forEach(t => t.stop());
    }
    setHasCamera(false);
  };

  const retake = () => {
    setCapturedImage(null);
    setAiResponse(null);
    setEditingMeal(null);
    setError(null);
    startCamera();
  };

  const analyzePhoto = async () => {
    if (!capturedImage) return;

    setAnalyzing(true);
    setError(null);

    try {
      const config = JSON.parse(localStorage.getItem('ai_nutrition_config') || '{}');
      if (!config.apiKey) {
        throw new Error('AI_API_KEY_NOT_SET');
      }

      const today = getTodayString();
      const meals = db.getMealsByDate(today);
      const todayMeals = meals.map(m => `${m.name} (${m.calories} ккал)`).join(', ') || 'ничего';

      // Call AI with base64 image
      const base64Data = capturedImage.split(',')[1];

      const response = await fetch(`${config.baseUrl}/chat/completions`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${config.apiKey}`
        },
        body: JSON.stringify({
          model: config.model || 'gpt-4o-mini',
          messages: [
            {
              role: 'user',
              content: [
                {
                  type: 'text',
                  text: 'Проанализируй это фото еды. Определи что это за блюдо и его примерную nutritional info (калории, белки, жиры, углеводы). Ответь кратко в формате: [ADD_MEAL:name=Блюдо:calories=XXX:protein=X:fat=X:carbs=X:mealType=breakfast]. Если не уверен — дай примерную оценку.'
                },
                {
                  type: 'image_url',
                  image_url: { url: `data:image/jpeg;base64,${base64Data}` }
                }
              ]
            }
          ],
          max_tokens: 500
        })
      });

      if (!response.ok) {
        throw new Error(`AI API error: ${response.status}`);
      }

      const data = await response.json();
      const aiText = data.choices[0].message.content;
      setAiResponse(aiText);

      const parsed = parseMealFromAI(aiText);
      if (parsed) {
        setEditingMeal({
          name: parsed.name,
          calories: parsed.calories,
          protein: parsed.protein,
          fat: parsed.fat,
          carbs: parsed.carbs,
          mealType: parsed.mealType || 'breakfast',
        });
        setMealType(parsed.mealType || 'breakfast');
      } else {
        // Try to extract info manually from response
