        setError('Настройте API-ключ AI в профиле для использования распознавания.');
      } else {
        setError('Не удалось распознать блюдо. Попробуйте ещё раз.');
      }
    }

    setAnalyzing(false);
  };

  const saveMeal = () => {
    if (!editingMeal) return;

    const meal = {
      date: getTodayString(),
      mealType,
      name: editingMeal.name,
      protein: editingMeal.protein * quantity,
      fat: editingMeal.fat * quantity,
      carbs: editingMeal.carbs * quantity,
      calories: editingMeal.calories * quantity,
      quantity,
    };

    db.addMeal(meal);
    navigate('/');
  };

  // No camera - show simple fallback
  if (!hasCamera && !capturedImage) {
    return (
      <div className="screen">
        <header className="header">
          <button className="icon-btn" onClick={() => navigate('/')}>
            <X size={24} />
          </button>
          <h1>Камера</h1>
        </header>

        <div className="camera-fallback">
          {error && <div className="error-message">{error}</div>}
          <p>Используйте кнопку ниже для добавления еды вручную</p>
          <button className="btn-primary" onClick={() => navigate('/add-product')}>
            Добавить продукт вручную
