GLASS_OPEN_D = BOX_D + 2;

// Corner bracket recess for additional securing
BRACKET_SIZE = 15;
BRACKET_DEPTH = 4;

// Ventilation groove (small slots for air circulation)
VENT_SLOTS = 8;
VENT_W = 2;
VENT_L = 40;

module vent_groove(x, y) {
    translate([x, y, FRAME_H - 1])
    cube([VENT_W, VENT_L, 2]);
}

difference() {
    union() {
        // Main frame body (rectangular with center hole)
        translate([0, 0, BOX_H])
        cube([TOTAL_W, TOTAL_D, FRAME_H], center=false);
    }

    // Glass opening (center cutout)
    translate([FRAME_W, FRAME_W, BOX_H - 0.5])
    cube([BOX_W, BOX_D, FRAME_H + 2], center=false);

    // Glass retainer lip (inner ledge that holds glass from falling)
    // Creates a 1.5mm lip around the opening
    translate([FRAME_W - LIP_T, FRAME_W - LIP_T, BOX_H + FRAME_H - LIP_H - 1])
    cube([BOX_W + LIP_T * 2, BOX_D + LIP_T * 2, LIP_H + 2], center=false);

    // Corner recesses for corner bracket screws
    translate([FRAME_W + 5, FRAME_W + 5, BOX_H - BRACKET_DEPTH + 1])
    cylinder(h=BRACKET_DEPTH + 2, r=2.5, center=false);
    translate([TOTAL_W - FRAME_W - 5, FRAME_W + 5, BOX_H - BRACKET_DEPTH + 1])
    cylinder(h=BRACKET_DEPTH + 2, r=2.5, center=false);
    translate([FRAME_W + 5, TOTAL_D - FRAME_W - 5, BOX_H - BRACKET_DEPTH + 1])
    cylinder(h=BRACKET_DEPTH + 2, r=2.5, center=false);
    translate([TOTAL_W - FRAME_W - 5, TOTAL_D - FRAME_W - 5, BOX_H - BRACKET_DEPTH + 1])
    cylinder(h=BRACKET_DEPTH + 2, r=2.5, center=false);
}

// Ventilation slots (milled into top of frame)
for (i = [0:VENT_SLOTS-1]) {
    vent_groove(FRAME_W + 20 + i * 18, FRAME_W + 10);
}

// Mounting holes for securing frame to walls
// These go through frame into top of walls
module mount_hole(x, y) {
    translate([x, y, BOX_H + FRAME_H/2])
    cylinder(h=FRAME_H + 2, r=1.8, center=true);
}

// Along long edges
for (x = [20, TOTAL_W/2, TOTAL_W - 20]) {
    mount_hole(x, FRAME_W/2);
    mount_hole(x, TOTAL_D - FRAME_W/2);
}
// Along short edges
for (y = [20, TOTAL_D/2, TOTAL_D - 20]) {
    mount_hole(FRAME_W/2, y);
    mount_hole(TOTAL_W - FRAME_W/2, y);
}

// ============================================================
// UV Exposure Box - Corner Clamp (single, print 4x)
// Secures glass plate in glass_frame
// L-shaped clamp with screw hole for M3 screw
// Prints without supports (flat on bed)
// ============================================================

// Clamp dimensions
CLAMP_W = 18;      // width of clamp body
CLAMP_L = 20;      // length of clamp arm
CLAMP_H = 6;       // height/thickness of clamp
SCREW_R = 1.5;     // M3 tap hole radius
LIP_H = 3;         // vertical lip height (grips over glass)
LIP_T = 2;         // lip thickness
PRESS_CLEAR = 0.3; // press-fit clearance

// Clamp matches glass frame dimensions
// Glass frame: 160x120mm interior, FRAME_W=12mm outer
// Corner clamp sits at 4 corners of frame

module corner_clamp() {
    difference() {
        union() {
            // Main clamp body (L-shape)
            translate([0, 0, 0])
            cube([CLAMP_W, CLAMP_L, CLAMP_H], center=false);

            // Vertical lip (grips glass from top)
            translate([CLAMP_W - LIP_T, 0, CLAMP_H])
            cube([LIP_T, CLAMP_L, LIP_H], center=false);

            // Overhang for glass edge
            translate([0, CLAMP_L - LIP_T, CLAMP_H])
            cube([CLAMP_W - PRESS_CLEAR, LIP_T, LIP_H], center=false);
        }

        // Screw hole (M3 tap, countersunk)
        translate([CLAMP_W / 2, CLAMP_L / 2, CLAMP_H - 1])
        cylinder(h=3, r=SCREW_R, center=false);

        // Countersink
        translate([CLAMP_W / 2, CLAMP_L / 2, CLAMP_H + 0.5])
        cylinder(h=2, r=3.5, center=false);
    }
}

// Rotate for better print orientation
rotate([0, 0, 45])
corner_clamp();

// ============================================================
// UV Exposure Box - Top Cover
// Covers the box, protects LED array, provides light seal
// Removable with handle for easy access
// Cutout for power switch and status LED indicator
// ============================================================

// Box exterior dimensions
BOX_W = 165;   // 160 + 2*2.5 wall
BOX_D = 125;   // 120 + 2*2.5 wall
COVER_H = 40;  // matches box height
COVER_T = 3;   // plate thickness
HANDLE_W = 60;
HANDLE_D = 15;
HANDLE_H = 8;

// Ventilation parameters
VENT_R = 5;
VENT_COUNT = 6;

// Glass frame parameters (for alignment rabbet)
FRAME_W = 12;
FRAME_H = 8;

// Screw parameters
SCREW_R = 1.5;  // M3 clearance
BOSS_R = 4;     // countersink boss
BOSS_H = 2;

module vent_hole(x, y) {
    translate([x, y, -1])
    cylinder(h=COVER_T + 2, r=VENT_R, center=true);
}

difference() {
    union() {
        // Main cover plate
        translate([0, 0, COVER_H])
        cube([BOX_W, BOX_D, COVER_T], center=false);

        // Handle (centered, recessed)
        translate([BOX_W/2 - HANDLE_W/2, BOX_D/2 - HANDLE_D/2, COVER_H - HANDLE_H])
        cube([HANDLE_W, HANDLE_D, HANDLE_H], center=false);

        // Handle reinforcement walls
        translate([BOX_W/2 - HANDLE_W/2 + 5, BOX_D/2 - HANDLE_D/2, COVER_H - HANDLE_H])
        cube([3, HANDLE_D, HANDLE_H]);
        translate([BOX_W/2 + HANDLE_W/2 - 8, BOX_D/2 - HANDLE_D/2, COVER_H - HANDLE_H])
        cube([3, HANDLE_D, HANDLE_H]);
    }

    // Alignment rabbet (fits glass frame outer edge)
    translate([-1, -1, COVER_H - 0.5])
    cube([BOX_W + 2, BOX_D + 2, COVER_T + 1], center=false);

    // Ventilation holes (2 rows of 3)
    vent_spacing = BOX_W / 4;
    for (i = [0:VENT_COUNT/2 - 1]) {
        vent_hole(vent_spacing + i * vent_spacing * 2, 20);
        vent_hole(vent_spacing + i * vent_spacing * 2, BOX_D - 20);
    }

    // Power switch cutout (recessed, centered on back)
    translate([BOX_W/2 - 8, BOX_D - 15, COVER_H - 1])
    cube([16, 12, COVER_T + 2], center=false);

    // Status LED hole (small, left of center)
    translate([BOX_W/2 - 35, BOX_D - 12, COVER_H - 1])
    cylinder(h=COVER_T + 2, r=3, center=true);

    // Shipping holes for assembly (used with alignment pins during assembly)
    // These get trimmed after assembly - 3mm holes at each corner
    translate([8, 8, COVER_H - 1])
    cylinder(h=COVER_T + 2, r=1.5, center=true);
    translate([BOX_W - 8, 8, COVER_H - 1])
    cylinder(h=COVER_T + 2, r=1.5, center=true);
    translate([8, BOX_D - 8, COVER_H - 1])
    cylinder(h=COVER_T + 2, r=1.5, center=true);
    translate([BOX_W - 8, BOX_D - 8, COVER_H - 1])
    cylinder(h=COVER_T + 2, r=1.5, center=true);
}

// Mounting bosses for securing cover to walls
module mounting_boss(x, y) {
    translate([x, y, COVER_H - BOSS_H])
    cylinder(h=BOSS_H, r=BOSS_R, center=false);
}

// Along edges - 3 per side
module edge_bosses_y(y) {
    for (x = [15, BOX_W/2, BOX_W - 15]) {
        mounting_boss(x, y);
    }
}
module edge_bosses_x(x) {
    for (y = [15, BOX_D/2, BOX_D - 15]) {
        mounting_boss(x, y);
    }
}

// Front and back edge bosses
edge_bosses_y(10);
edge_bosses_y(BOX_D - 10);
// Left and right edge bosses
edge_bosses_x(10);
edge_bosses_x(BOX_W - 10);

