// UV Exposure Box - Power Switch Mount
// Secures ON/OFF toggle switch to back wall
// Includes 12V DC barrel jack for power input
// Fits standard 16mm panel-mount toggle switch
// ============================================================

// Box dimensions
BOX_W = 165;
BOX_D = 125;
BOX_H = 40;
WALL_T = 2.5;

// Switch parameters
SWITCH_H = 16;      // panel mount height
SWITCH_BODY = 13;   // body diameter
MOUNT_R = 8;        // mounting nut radius
NUT_H = 5;          // nut thickness

// Barrel jack parameters
JACK_OD = 12;       // outer diameter
JACK_ID = 5.5;      // center pin diameter
JACK_FLANGE = 15;   // flange diameter
JACK_MOUNT_R = 8;   // mounting hole radius

// Mount bracket parameters
BRACKET_W = 30;
BRACKET_H = 25;
BRACKET_T = 3;

// Standoff for mounting to wall
STANDOFF_R = 4;
STANDOFF_H = WALL_T + 2;
TAP_R = 1.5;  // M3 tap

// LED indicator
INDICATOR_R = 3;

module switch_mount() {
    difference() {
        union() {
            // Main mounting bracket
            translate([-BRACKET_W/2, -BRACKET_H/2, 0])
            cube([BRACKET_W, BRACKET_H, BRACKET_T], center=false);

            // Standoff post for wall mounting
            translate([0, 0, BRACKET_T])
            cylinder(h=STANDOFF_H, r=STANDOFF_R, center=false);

            // Switch body recess collar
            translate([0, BRACKET_H/3, BRACKET_T/2])
            cylinder(h=BRACKET_T, r=MOUNT_R, center=true);
        }

        // Switch mounting hole (center)
        translate([0, BRACKET_H/3, BRACKET_T/2])
        cylinder(h=BRACKET_T + 2, r=SWITCH_BODY/2, center=true);

        // Switch retaining nut slot
        translate([0, BRACKET_H/3, BRACKET_T - 1])
        cylinder(h=NUT_H + 1, r=MOUNT_R + 0.5, center=true);

        // Barrel jack mounting hole (offset below switch)
        translate([0, -BRACKET_H/4, BRACKET_T/2])
        cylinder(h=BRACKET_T + 2, r=JACK_FLANGE/2, center=true);

        // Barrel jack center hole
        translate([0, -BRACKET_H/4, BRACKET_T/2])
        cylinder(h=BRACKET_T + 5, r=JACK_ID/2 + 0.5, center=true);

        // Standoff tap hole (M3)
        translate([0, 0, -1])
        cylinder(h=STANDOFF_H + 5, r=TAP_R, center=false);

        // Wire routing slot (between switch and jack)
        translate([-3, 0, BRACKET_T + 1])
        cube([6, BRACKET_H/2, 2], center=false);
    }
}

