module led_hole() {
    translate([BRACKET_W/2 - 5, BRACKET_H/2 - 5, BRACKET_T/2])
    cylinder(h=BRACKET_T + 2, r=INDICATOR_R, center=true);
}

// Render mount
switch_mount();

