translate([BOX_W/2, BOX_D + WALL_T + 5, BOX_H/2])
rotate([90, 0, 0])
switch_mount();

import { useState, useEffect } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import { Plus, Search, ArrowLeft, Trash2, Edit2, Coffee, Sunrise, Sunset, Utensils, X } from 'lucide-react';
import { db } from '../utils/db';
import { getTodayString, formatCalories, calcPercentage } from '../utils/nutrition';
import { mealTypes, defaultProducts } from '../data/defaultData';

export default function MealScreen() {
  const { type } = useParams();
  const navigate = useNavigate();
  const [meals, setMeals] = useState([]);
  const [showAddModal, setShowAddModal] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);
  const [editingMeal, setEditingMeal] = useState(null);

  const mealTypeInfo = mealTypes.find(t => t.id === type) || { id: type, name: 'Приём пищи', icon: 'utensils' };

  const today = getTodayString();
  const profile = db.getProfile();

  useEffect(() => {
    loadMeals();
  }, [type]);

  const loadMeals = () => {
    const todayMeals = db.getMealsByDate(today);
    setMeals(todayMeals.filter(m => m.mealType === type));
  };

  // Calculate totals for this meal type
  const totals = meals.reduce((acc, m) => ({
    protein: acc.protein + (m.protein || 0),
    fat: acc.fat + (m.fat || 0),
    carbs: acc.carbs + (m.carbs || 0),
    calories: acc.calories + (m.calories || 0),
  }), { protein: 0, fat: 0, carbs: 0, calories: 0 });

  // Calculate targets for percentage display
  let targets = { calories: 2000, protein: 150, fat: 65, carbs: 250 };
  if (profile) {
    const { calculateBMR, calculateTDEE, calculateTargetCalories, calculateMacros } = require('../utils/nutrition');
    const bmr = calculateBMR(profile.weight, profile.height, profile.age, profile.sex);
    const tdee = calculateTDEE(bmr, profile.activityLevel);
    const targetCals = calculateTargetCalories(tdee, profile.goal);
    const macros = calculateMacros(targetCals, profile.goal, profile.activityLevel);
    targets = { calories: targetCals, ...macros };
  }

  // Get icon for meal type
  const MealIcon = () => {
    switch (type) {
      case 'breakfast': return <Sunrise size={24} />;
      case 'lunch': return <Coffee size={24} />;
      case 'dinner': return <Sunset size={24} />;
      case 'snack': return <Utensils size={24} />;
      default: return <Utensils size={24} />;
    }
  };

  const handleDelete = (mealId) => {
    if (confirm('Удалить этот приём пищи?')) {
      db.deleteMeal(mealId);
      loadMeals();
    }
  };

  const handleEdit = (meal) => {
    setEditingMeal(meal);
    setShowEditModal(true);
  };

  return (
    <div className="screen">
      <header className="header">
        <button className="icon-btn" onClick={() => navigate('/')}>
          <ArrowLeft size={24} />
        </button>
        <div className="header-title-group">
          <MealIcon />
          <h1>{mealTypeInfo.name}</h1>
        </div>
        <button className="icon-btn" onClick={() => setShowAddModal(true)}>
          <Plus size={24} />
        </button>
      </header>

      {/* Summary Card */}
      <div className="meal-summary">
        <div className="meal-summary-calories">
          <span className="meal-summary-value">{Math.round(totals.calories)}</span>
          <span className="meal-summary-label">ккал</span>
        </div>
        <div className="meal-summary-macros">
          <span className="macro-tag protein">Б: {Math.round(totals.protein)}г</span>
          <span className="macro-tag fat">Ж: {Math.round(totals.fat)}г</span>
          <span className="macro-tag carbs">У: {Math.round(totals.carbs)}г</span>
        </div>
        <div className="meal-summary-progress">
          <div className="progress-bar-full">
            <div
              className={`progress-fill ${totals.calories > targets.calories / 4 ? 'over' : ''}`}
              style={{ width: `${Math.min((totals.calories / (targets.calories / 4)) * 100, 100)}%` }}
            />
          </div>
          <span className="progress-label">{Math.round(calcPercentage(totals.calories, targets.calories / 4))}% от нормы</span>
        </div>
      </div>

      {/* Meals List */}
      <div className="meal-items-list">
        {meals.length === 0 ? (
          <div className="empty-state">
            <MealIcon />
            <p>Пока нет записей</p>
            <button className="btn-primary" onClick={() => setShowAddModal(true)}>
              <Plus size={18} /> Добавить
            </button>
          </div>
        ) : (
          meals.map(meal => (
            <div key={meal.id} className="meal-item-card">
              <div className="meal-item-main">
                <div className="meal-item-info">
                  <span className="meal-item-name">{meal.name}</span>
                  <span className="meal-item-cal">{Math.round(meal.calories)} ккал</span>
                </div>
                <div className="meal-item-macros">
                  <span className="meal-item-macro protein">Б: {Math.round(meal.protein || 0)}г</span>
                  <span className="meal-item-macro fat">Ж: {Math.round(meal.fat || 0)}г</span>
                  <span className="meal-item-macro carbs">У: {Math.round(meal.carbs || 0)}г</span>
                </div>
                {meal.quantity && meal.quantity !== 1 && (
                  <span className="meal-item-qty">×{meal.quantity}</span>
                )}
              </div>
              <div className="meal-item-actions">
                <button className="icon-btn-sm" onClick={() => handleEdit(meal)}>
                  <Edit2 size={16} />
                </button>
                <button className="icon-btn-sm danger" onClick={() => handleDelete(meal.id)}>
                  <Trash2 size={16} />
                </button>
              </div>
            </div>
          ))
        )}
      </div>

      <button className="btn-primary" onClick={() => setShowAddModal(true)} style={{ marginTop: '16px' }}>
        <Plus size={18} /> Добавить в {mealTypeInfo.name}
      </button>

      {/* Add Modal */}
      {showAddModal && (
        <AddMealModal
          mealType={type}
          onClose={() => setShowAddModal(false)}
          onAdded={loadMeals}
        />
      )}

      {/* Edit Modal */}
      {showEditModal && editingMeal && (
        <EditMealModal
          meal={editingMeal}
          mealType={type}
          onClose={() => { setShowEditModal(false); setEditingMeal(null); }}
          onUpdated={loadMeals}
        />
      )}
    </div>
  );
}

