import { useState, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, Target, Calendar, TrendingDown, TrendingUp, Minus, Info } from 'lucide-react';
import { db } from '../utils/db';
import { calculateBMR, calculateTDEE, calculateTargetCalories, calculateMacros, getTodayString, formatDate } from '../utils/nutrition';

export default function GoalPredictionScreen() {
  const navigate = useNavigate();
  const profile = db.getProfile();
  const weights = db.getWeights().sort((a, b) => new Date(a.date) - new Date(b.date));

  const { prediction, trendRate, currentWeight, targetWeight, startWeight } = useMemo(() => {
    if (!profile?.weight || weights.length < 2) {
      return { prediction: null, trendRate: 0, currentWeight: null, targetWeight: null, startWeight: null };
    }

    const sorted = [...weights].sort((a, b) => new Date(a.date) - new Date(b.date));
    const first = sorted[0];
    const last = sorted[sorted.length - 1];
    const daysDiff = Math.max(1, (new Date(last.date) - new Date(first.date)) / (1000 * 60 * 60 * 24));
    const totalDiff = parseFloat(last.weight) - parseFloat(first.weight);
    const dailyRate = totalDiff / daysDiff; // kg per day
    const weeklyRate = dailyRate * 7;        // kg per week

    const current = parseFloat(last.weight);
    const target = parseFloat(profile.weight);
    const goalType = profile.goal || 'maintain';
    const isLoss = goalType === 'loss';
    const isGain = goalType === 'gain';
    const diff = current - target;
    const absDiff = Math.abs(diff);

    let daysRemaining = null;
    if ((isLoss && diff > 0) || (isGain && diff < 0)) {
      if (Math.abs(weeklyRate) > 0.001) {
        daysRemaining = Math.ceil(absDiff / Math.abs(weeklyRate) * 7);
      }
    }

    const projectedDate = daysRemaining !== null
      ? new Date(Date.now() + daysRemaining * 24 * 60 * 60 * 1000)
      : null;

    return {
      prediction: daysRemaining !== null ? {
        daysRemaining,
        projectedDate: projectedDate?.toISOString().split('T')[0] || null,
        weeklyRate: Math.abs(weeklyRate).toFixed(2),
      } : null,
      trendRate: weeklyRate,
      currentWeight: current,
      targetWeight: target,
      startWeight: parseFloat(first.weight),
    };
  }, [profile, weights]);

  // Calculate progress percentage
  const getProgress = () => {
    if (!startWeight || !currentWeight || !targetWeight) return 0;
    const total = Math.abs(startWeight - targetWeight);
    if (total === 0) return 100;
    const done = Math.abs(startWeight - currentWeight);
    return Math.min(100, Math.round((done / total) * 100));
  };

  const progress = getProgress();
  const goalType = profile?.goal || 'maintain';
  const isLoss = goalType === 'loss';
  const isGain = goalType === 'gain';

  if (!profile?.weight) {
    return (
      <div className="screen">
        <header className="header">
          <button className="icon-btn" onClick={() => navigate('/profile')}>
            <ArrowLeft size={24} />
          </button>
          <h1>Прогноз цели</h1>
        </header>
        <div className="empty-state" style={{ marginTop: 60 }}>
          <Target size={48} style={{ opacity: 0.3 }} />
          <p>Заполните профиль и цель веса в Профиле</p>
          <button className="btn-primary" onClick={() => navigate('/profile')}>
            Перейти в Профиль
          </button>
        </div>
        <Navigation navigate={navigate} />
      </div>
    );
  }

  return (
    <div className="screen">
      <header className="header">
        <button className="icon-btn" onClick={() => navigate('/profile')}>
          <ArrowLeft size={24} />
        </button>
        <h1>Прогноз цели</h1>
      </header>

      <div className="goal-prediction-container">
        {/* Current vs Target Card */}
        <div className="goal-main-card">
          <div className="goal-icon">
            <Target size={32} />
          </div>
          <div className="goal-weights">
            <div className="goal-weight-item">
              <span className="goal-weight-label">Сейчас</span>
              <span className="goal-weight-value">{currentWeight} кг</span>
            </div>
            <div className="goal-arrow">→</div>
            <div className="goal-weight-item target">
              <span className="goal-weight-label">Цель</span>
              <span className="goal-weight-value">{targetWeight} кг</span>
            </div>
          </div>
          <div className="goal-diff-badge" style={{
            background: (isLoss && trendRate < 0) || (isGain && trendRate > 0) ? 'var(--success)' : 'var(--warning)'
          }}>
            {isLoss ? 'Похудение' : isGain ? 'Набор массы' : 'Поддержание'}
          </div>
        </div>

        {/* Progress Bar */}
