};

function getStatus(value, param) {
  if (value === null || value === undefined || value === '') return 'empty';
  const v = parseFloat(value);
  if (isNaN(v)) return 'empty';
  if (v < param.normalMin) return 'low';
  if (v > param.normalMax) return 'high';
  return 'normal';
}

function getStatusLabel(status) {
  if (status === 'low') return 'Низко';
  if (status === 'high') return 'Высоко';
  if (status === 'normal') return 'Норма';
  return '—';
}

