export default function DailySummaryScreen() {
  const navigate = useNavigate();
  const today = getTodayString();
  const profile = db.getProfile();
  const meals = db.getMealsByDate(today);

  const totals = useMemo(() => meals.reduce((acc, m) => ({
    protein: acc.protein + (m.protein || 0),
    fat: acc.fat + (m.fat || 0),
    carbs: acc.carbs + (m.carbs || 0),
    calories: acc.calories + (m.calories || 0),
  }), { protein: 0, fat: 0, carbs: 0, calories: 0 }), [meals]);

  let targets = { calories: 2000, protein: 150, fat: 65, carbs: 250 };
  if (profile) {
    const bmr = calculateBMR(profile.weight, profile.height, profile.age, profile.sex);
    const tdee = calculateTDEE(bmr, profile.activityLevel);
    const targetCals = calculateTargetCalories(tdee, profile.goal);
    const macros = calculateMacros(targetCals, profile.goal, profile.activityLevel);
    targets = { calories: targetCals, ...macros };
  }

  const [summary, setSummary] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const generateSummary = async () => {
    setLoading(true);
    setError(null);
    try {
      const config = { apiKey: localStorage.getItem('ai_nutrition_config') ? JSON.parse(localStorage.getItem('ai_nutrition_config')).apiKey : '' };
      if (!config.apiKey) {
        setError('Настройте API ключ в AI Помощнике');
        setLoading(false);
        return;
      }

      const mealList = meals.map(m => `${m.name}: ${m.calories} ккал, Б:${m.protein}г Ж:${m.fat}г У:${m.carbs}г`).join('\n');
      const remainingCals = Math.max(0, targets.calories - totals.calories);

      const prompt = `Проанализируй мой день питания:\n\nЕда за день:\n${mealList || 'Нет записей'}\n\nИтого: ${Math.round(totals.calories)}/${targets.calories} ккал\nБ:${Math.round(totals.protein)}/${targets.protein}г Ж:${Math.round(totals.fat)}/${targets.fat}г У:${Math.round(totals.carbs)}/${targets.carbs}г\n\nremaining calories: ${Math.round(remainingCals)} ккал\n\nДай краткий анализ на русском: что хорошо, что нужно исправить, и совет на завтра. Формат:\nХОРОШО: ...\nИСПРАВИТЬ: ...\nСОВЕТ: ...`;

      const result = await askAI([{ role: 'user', content: prompt }], {
        profile,
        todayMeals: mealList,
        remainingCalories: remainingCals,
      });

      // Parse the result into structured sections
