    if (!profile?.weight || weights.length < 2) {
      return { prediction: null, trendRate: 0, currentWeight: null, targetWeight: null, startWeight: null };
    }

    const sorted = [...weights].sort((a, b) => new Date(a.date) - new Date(b.date));
    const first = sorted[0];
    const last = sorted[sorted.length - 1];
    const daysDiff = Math.max(1, (new Date(last.date) - new Date(first.date)) / (1000 * 60 * 60 * 24));
    const totalDiff = parseFloat(last.weight) - parseFloat(first.weight);
    const dailyRate = totalDiff / daysDiff; // kg per day
    const weeklyRate = dailyRate * 7;        // kg per week

    const current = parseFloat(last.weight);
    const target = parseFloat(profile.weight);
    const goalType = profile.goal || 'maintain';
    const isLoss = goalType === 'loss';
    const isGain = goalType === 'gain';
    const diff = current - target;
    const absDiff = Math.abs(diff);

    let daysRemaining = null;
    if ((isLoss && diff > 0) || (isGain && diff < 0)) {
      if (Math.abs(weeklyRate) > 0.001) {
        daysRemaining = Math.ceil(absDiff / Math.abs(weeklyRate) * 7);
      }
    }

    const projectedDate = daysRemaining !== null
      ? new Date(Date.now() + daysRemaining * 24 * 60 * 60 * 1000)
      : null;

    return {
      prediction: daysRemaining !== null ? {
        daysRemaining,
        projectedDate: projectedDate?.toISOString().split('T')[0] || null,
        weeklyRate: Math.abs(weeklyRate).toFixed(2),
      } : null,
      trendRate: weeklyRate,
      currentWeight: current,
      targetWeight: target,
      startWeight: parseFloat(first.weight),
    };
