}

function findSuggestions(remaining, products) {
  // Find products that help fill the remaining macros efficiently
  const sorted = [...products].sort((a, b) => {
    const aScore = (a.protein / Math.max(remaining.protein, 1)) + (a.fat / Math.max(remaining.fat, 1)) + (a.carbs / Math.max(remaining.carbs, 1));
    const bScore = (b.protein / Math.max(remaining.protein, 1)) + (b.fat / Math.max(remaining.fat, 1)) + (b.carbs / Math.max(remaining.carbs, 1));
    return bScore - aScore;
  });

  const suggestions = [];
  let remainingCals = remaining.calories;
  let remainingProtein = remaining.protein;
  let remainingFat = remaining.fat;
  let remainingCarbs = remaining.carbs;

  for (const p of sorted) {
    if (suggestions.length >= 5) break;
    if (p.calories > remainingCals * 1.2 && p.calories > 100) continue;

    const qty = Math.min(
      Math.max(1, Math.round(remainingCals / Math.max(p.calories, 1))),
      3
    );

    suggestions.push({
      product: p,
      quantity: qty,
      totalCalories: Math.round(p.calories * qty),
      totalProtein: Math.round((p.protein || 0) * qty),
      totalFat: Math.round((p.fat || 0) * qty),
      totalCarbs: Math.round((p.carbs || 0) * qty),
    });

    remainingCals -= p.calories * qty;
    remainingProtein -= (p.protein || 0) * qty;
    remainingFat -= (p.fat || 0) * qty;
    remainingCarbs -= (p.carbs || 0) * qty;
  }

  return suggestions;
}

function getMealTypeSuggestions(remaining) {
  // Suggest meal type based on remaining macros
  const cals = remaining.calories;
  if (cals < 200) {
    return { type: 'snack', label: 'Лёгкий перекус', icon: '🍎' };
  } else if (cals < 400) {
    return { type: 'snack', label: 'Перекус', icon: '🥜' };
  } else if (cals < 600) {
    return { type: 'lunch', label: 'Обед', icon: '🍽️' };
  } else {
    return { type: 'dinner', label: 'Ужин', icon: '🌙' };
  }
}

