  const getStats = () => {
    if (weights.length === 0) return null;
    const sorted = [...weights].sort((a, b) => new Date(a.date) - new Date(b.date));
    const startWeight = parseFloat(sorted[0].weight);
    const currentWeight = parseFloat(sorted[sorted.length - 1].weight);
    const diff = currentWeight - startWeight;
    return {
      startWeight,
      currentWeight,
      diff,
      entries: weights.length,
    };
  };
  const stats = getStats();

  const handleAddWeight = () => {
    if (!newWeight) return;
    db.addWeight({ weight: parseFloat(newWeight) });
    setNewWeight('');
    setSaved(true);
    setTimeout(() => setSaved(false), 2000);
  };

  const handleDeleteWeight = (id) => {
    const filtered = db.getWeights().filter(w => w.id !== id);
    db.saveWeights(filtered);
  };

