    const sorted = [...weights].sort((a, b) => new Date(a.date) - new Date(b.date)).slice(-14);
    if (sorted.length < 2) return null;
    const weights_nums = sorted.map(w => parseFloat(w.weight));
    const minW = Math.min(...weights_nums);
    const maxW = Math.max(...weights_nums);
    const range = maxW - minW || 1;
    return { entries: sorted, minW, maxW, range };
  };
  const chartData = getChartData();

