          </div>
        )}
      </div>

      {/* Stats Summary */}
      {stats && (
        <div className="weight-stats-row">
          <div className="weight-stat-item">
            <span className="weight-stat-label">Старт</span>
            <span className="weight-stat-value">{stats.startWeight} кг</span>
          </div>
          <div className="weight-stat-item">
            <span className="weight-stat-label">Сейчас</span>
            <span className="weight-stat-value">{stats.currentWeight} кг</span>
          </div>
          <div className="weight-stat-item">
            <span className="weight-stat-label">Изменение</span>
            <span className={`weight-stat-value ${stats.diff < 0 ? 'green' : stats.diff > 0 ? 'red' : ''}`}>
              {stats.diff > 0 ? '+' : ''}{stats.diff.toFixed(1)} кг
              {stats.diff < 0 ? <TrendingDown size={14} /> : stats.diff > 0 ? <TrendingUp size={14} /> : null}
            </span>
          </div>
        </div>
      )}

      {/* ASCII Weight Chart */}
      {chartData && (
        <div className="weight-chart-section">
          <h3 className="section-title">Динамика (14 дней)</h3>
          <div className="weight-chart">
            <div className="chart-y-labels">
              <span>{chartData.maxW.toFixed(1)}</span>
              <span>{((chartData.maxW + chartData.minW) / 2).toFixed(1)}</span>
              <span>{chartData.minW.toFixed(1)}</span>
            </div>
            <div className="chart-bars">
              {chartData.entries.map((entry, i) => {
                const heightPct = ((parseFloat(entry.weight) - chartData.minW) / chartData.range) * 100;
                return (
                  <div key={entry.id} className="chart-bar-wrapper" title={`${entry.weight} кг · ${formatDate(entry.date)}`}>
                    <div className="chart-bar" style={{ height: `${Math.max(heightPct, 10)}%` }} />
                    {i === chartData.entries.length - 1 && (
                      <span className="chart-bar-label">{entry.weight}</span>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      )}

      {/* Add Weight Form */}
      <div className="weight-add-card">
        <h3 className="section-title">
          <Plus size={18} />
          Записать вес
