            type="number"
            value={newWeight}
            onChange={e => setNewWeight(e.target.value)}
            placeholder="70.5"
            step="0.1"
            min="30"
            max="300"
            className="weight-input"
          />
          <span className="weight-input-unit">кг</span>
          <button className="btn-primary" onClick={handleAddWeight}>Добавить</button>
        </div>
        {saved && <div className="success-message">✓ Вес записан!</div>}
      </div>

      {/* Weight History */}
      {weights.length > 0 && (
        <div className="weight-history-section">
          <h3 className="section-title">История</h3>
          <div className="weight-history-list">
            {weights.slice(0, 30).map(entry => (
              <div key={entry.id} className="weight-history-item">
                <span className="weight-history-date">{formatDate(entry.date)}</span>
                <span className="weight-history-value">{entry.weight} кг</span>
                <button
                  className="weight-delete-btn"
                  onClick={() => handleDeleteWeight(entry.id)}
                >
                  <Trash2 size={14} />
                </button>
              </div>
            ))}
          </div>
        </div>
      )}

      <Navigation />
    </div>
  );
}

