}

RATE_LIMIT = 60  # requests per minute per API key
rate_limit_store = {}  # {api_key: [(timestamp, count), ...]}

def check_rate_limit(api_key: str) -> bool:
    now = time.time()
    if api_key not in rate_limit_store:
        rate_limit_store[api_key] = []
    # Clean old entries (> 1 min)
    rate_limit_store[api_key] = [
        t for t in rate_limit_store[api_key] if now - t < 60
    ]
    if len(rate_limit_store[api_key]) >= RATE_LIMIT:
        return False
    rate_limit_store[api_key].append(now)
    return True

def get_provider_for_model(model_id: str) -> tuple[str, str]:
    """Returns (provider_name, base_url)"""
    if model_id in ["qwen-14b"]:
        return "ollama", MODEL_PROVIDERS["ollama"]["base_url"]
    elif model_id.startswith("claude"):
        return "anthropic", MODEL_PROVIDERS["anthropic"]["base_url"]
    elif model_id.startswith("gpt"):
        return "openai", MODEL_PROVIDERS["openai"]["base_url"]
    else:
        return "openai", MODEL_PROVIDERS["openai"]["base_url"]

def estimate_tokens(text: str) -> int:
    """Rough token estimation: ~4 chars per token"""
    return len(text) // 4

def deduct_cost(user_id: int, model_id: str, input_text: str, output_text: str):
    """Deduct cost from user balance based on tokens used"""
    if model_id not in MODEL_PRICING:
        return  # Unknown model, no charge (e.g. local Ollama)

    prices = MODEL_PRICING[model_id]
    input_tokens = estimate_tokens(input_text)
    output_tokens = estimate_tokens(output_text)

    cost = (input_tokens / 1_000_000) * prices["input"] + \
           (output_tokens / 1_000_000) * prices["output"]

    # Convert to tokens (1 token = $0.0001 at base rate)
    token_cost = int(cost / 0.0001)

    conn = get_db()
    conn.execute(
        "UPDATE users SET balance = balance - ? WHERE id = ? AND balance >= ?",
        (token_cost, user_id, token_cost)
    )
    conn.execute(
        "INSERT INTO transactions (user_id, amount, description) VALUES (?, ?, ?)",
        (user_id, -token_cost, f"API call: {model_id}")
    )
    conn.commit()

    # Check if update succeeded (balance was enough)
    cursor = conn.execute("SELECT balance FROM users WHERE id = ?", (user_id,))
    row = cursor.fetchone()
    conn.close()

    if row and row[0] < 0:
        raise HTTPException(status_code=402, detail="Insufficient balance")

def verify_api_key(api_key: str) -> Optional[int]:
    """Verify API key and return user_id, or None"""
    conn = get_db()
    cursor = conn.execute(
        "SELECT user_id FROM api_keys WHERE key = ?",
        (api_key,)
    )
    row = cursor.fetchone()
    if row:
        conn.execute(
            "UPDATE api_keys SET last_used = CURRENT_TIMESTAMP WHERE key = ?",
            (api_key,)
        )
        conn.commit()
    conn.close()
    return row[0] if row else None

async def proxy_to_provider(provider: str, base_url: str, model: str, messages: list, 
                            stream: bool, api_key_env: str, **kwargs):
    """Proxy request to actual AI provider"""
    headers = {"Authorization": f"Bearer {os.environ.get(api_key_env, '')}"}

    if provider == "anthropic":
        headers["x-api-key"] = os.environ.get(api_key_env, "")
        headers["anthropic-version"] = "2023-06-01"
        # Transform messages format for Claude
        system_msg = ""
        filtered_msgs = []
        for m in messages:
            if m["role"] == "system":
                system_msg = m["content"]
            else:
                filtered_msgs.append({"role": m["role"], "content": m["content"]})

        body = {
            "model": model,
            "messages": filtered_msgs,
            "stream": stream,
        }
        if system_msg:
            body["system"] = system_msg
        if "max_tokens" in kwargs:
            body["max_tokens"] = kwargs["max_tokens"]
        if "temperature" in kwargs:
            body["temperature"] = kwargs["temperature"]
    else:
        # OpenAI-compatible
        body = {
            "model": model,
            "messages": messages,
            "stream": stream,
        }
        if "max_tokens" in kwargs:
            body["max_tokens"] = kwargs["max_tokens"]
        if "temperature" in kwargs:
            body["temperature"] = kwargs["temperature"]

    async with httpx.AsyncClient(timeout=120.0) as client:
        resp = await client.post(
            f"{base_url}/chat/completions",
            headers=headers,
            json=body
        )
        return resp

