export const supportedLanguages = [
  { code: 'ru', name: 'Русский' },
  { code: 'en', name: 'English' },
];

export function getCurrentLanguage() {
  try {
    return localStorage.getItem('app_language') || DEFAULT_LANG;
  } catch {
    return DEFAULT_LANG;
  }
}

export function setLanguage(lang) {
  try {
    localStorage.setItem('app_language', lang);
  } catch {}
}

export function t(key) {
  const lang = getCurrentLanguage();
  const translation = translations[key];
  if (!translation) {
    return key;
  }
  return translation[lang] || translation[DEFAULT_LANG] || key;
}

export default { t, getCurrentLanguage, setLanguage, supportedLanguages };

import { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { db } from '../utils/db';
import { getTodayString } from '../utils/nutrition';

export default function GoalAchievedScreen() {
  const navigate = useNavigate();
  const [stats, setStats] = useState({ weightLost: 0, daysTracking: 0, mealsLogged: 0 });
  const [showConfetti, setShowConfetti] = useState(true);

  useEffect(() => {
    // Calculate stats
    const profile = db.getProfile();
    const weights = db.getWeights();
    const allMeals = [];

    // Get all meals across dates
    for (let i = 0; i < 90; i++) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const dateStr = date.toISOString().split('T')[0];
      const dayMeals = db.getMealsByDate(dateStr);
      allMeals.push(...dayMeals);
    }

    let weightLost = 0;
    if (weights.length >= 2) {
      const sorted = [...weights].sort((a, b) => new Date(b.date) - new Date(a.date));
      weightLost = Math.abs(sorted[0].weight - (profile?.goalWeight || sorted[0].weight));
    }

    const uniqueDates = new Set(allMeals.map(m => m.date));
    const daysTracking = uniqueDates.size;
    const mealsLogged = allMeals.length;

    setStats({ weightLost, daysTracking, mealsLogged });
  }, []);

  const handleContinue = () => {
    navigate('/');
  };

  const handleNewGoal = () => {
    navigate('/profile');
  };

  const confettiPieces = Array.from({ length: 30 }, (_, i) => ({
    id: i,
    left: Math.random() * 100,
    delay: Math.random() * 3,
    color: ['#FFD700', '#FF6B6B', '#4ECDC4', '#45B7D1', '#96CEB4', '#FF9FF3'][i % 6],
    size: 8 + Math.random() * 8,
  }));

  return (
    <div className="screen goal-achieved-screen">
      {showConfetti && (
        <div className="confetti-container">
          {confettiPieces.map(p => (
            <div
              key={p.id}
              className="confetti-piece"
              style={{
                left: `${p.left}%`,
                animationDelay: `${p.delay}s`,
                backgroundColor: p.color,
                width: `${p.size}px`,
                height: `${p.size}px`,
              }}
            />
          ))}
        </div>
      )}

      <div className="goal-achieved-content">
        <div className="goal-achieved-emoji">🏆</div>
        <h1 className="goal-achieved-title">🎉 Цель достигнута! 🎉</h1>
        <p className="goal-achieved-message">Поздравляем! Вы достигли своей цели!</p>

        <div className="goal-achieved-stats">
          <div className="goal-stat-card">
            <span className="goal-stat-icon">⚖️</span>
            <span className="goal-stat-value">{stats.weightLost.toFixed(1)}</span>
            <span className="goal-stat-label">кг потеряно</span>
          </div>
          <div className="goal-stat-card">
            <span className="goal-stat-icon">📅</span>
            <span className="goal-stat-value">{stats.daysTracking}</span>
            <span className="goal-stat-label">дней отслеживания</span>
          </div>
          <div className="goal-stat-card">
            <span className="goal-stat-icon">🍽️</span>
            <span className="goal-stat-value">{stats.mealsLogged}</span>
            <span className="goal-stat-label">приёмов пищи</span>
          </div>
        </div>

        <div className="goal-achieved-actions">
          <button className="btn-primary" onClick={handleContinue}>
            Продолжить
          </button>
          <button className="btn-secondary" onClick={handleNewGoal}>
            Новая цель
          </button>
        </div>
      </div>
    </div>
  );
}

