    if (form.weight && form.height && form.age) {
      db.saveProfile(form);
    }
    localStorage.setItem('onboarding_completed', 'true');
    navigate('/');
  };

  let preview = { target: 0, macros: { protein: 0, fat: 0, carbs: 0 } };
