  }

  const currentStep = STEPS[step];

  return (
    <div className="screen onboarding-screen">
      <div className="onboarding-container">
        {step > 0 && (
          <button className="onboarding-skip" onClick={handleSkip}>
            Пропустить
          </button>
        )}

        <div className="onboarding-progress">
          {STEPS.map((_, i) => (
            <div
              key={i}
              className={`progress-dot ${i <= step ? 'active' : ''}`}
            />
          ))}
        </div>

        <div className="onboarding-content">
          <div className="onboarding-emoji">{currentStep.emoji}</div>
          <h1 className="onboarding-title">{currentStep.title}</h1>
          <p className="onboarding-desc">{currentStep.description}</p>
        </div>

        <div className="onboarding-actions">
          {step < STEPS.length - 1 ? (
            <>
              <button className="btn-secondary" onClick={handleNext}>
                Далее
              </button>
              {step === STEPS.length - 2 && (
                <button className="btn-primary" onClick={handleGetStarted}>
                  Начать
                </button>
              )}
            </>
          ) : (
            <button className="btn-primary" onClick={handleGetStarted}>
              Начать
            </button>
          )}
        </div>

        <div className="onboarding-dots">
          {STEPS.map((_, i) => (
            <button
              key={i}
              className={`dot ${i === step ? 'active' : ''}`}
              onClick={() => setStep(i)}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

// LocalStorage Database Utilities for AI Nutrition App

const DB_KEYS = {
  PRODUCTS: 'nutrition_products',
  MEALS: 'nutrition_meals',
  PROFILE: 'nutrition_profile',
  WEIGHTS: 'nutrition_weights',
  WORKOUTS: 'nutrition_workouts',
};

export const db = {
  // Products (local food database)
  getProducts: () => {
    const data = localStorage.getItem(DB_KEYS.PRODUCTS);
    return data ? JSON.parse(data) : [];
  },

  saveProducts: (products) => {
    localStorage.setItem(DB_KEYS.PRODUCTS, JSON.stringify(products));
  },

  addProduct: (product) => {
    const products = db.getProducts();
    const newProduct = {
      id: Date.now().toString(),
      ...product,
      createdAt: new Date().toISOString(),
    };
    products.push(newProduct);
    db.saveProducts(products);
    return newProduct;
  },

  searchProducts: (query) => {
    const products = db.getProducts();
    if (!query) return products;
    const q = query.toLowerCase();
    return products.filter(p => 
      p.name.toLowerCase().includes(q) ||
      p.category?.toLowerCase().includes(q)
    );
  },

  // Meals (meal log entries)
  getMeals: () => {
    const data = localStorage.getItem(DB_KEYS.MEALS);
    return data ? JSON.parse(data) : [];
  },

  saveMeals: (meals) => {
    localStorage.setItem(DB_KEYS.MEALS, JSON.stringify(meals));
  },

  addMeal: (meal) => {
    const meals = db.getMeals();
    const newMeal = {
      id: Date.now().toString(),
      ...meal,
      createdAt: new Date().toISOString(),
    };
    meals.push(newMeal);
    db.saveMeals(meals);
    return newMeal;
  },

  getMealsByDate: (dateStr) => {
    const meals = db.getMeals();
    return meals.filter(m => m.date === dateStr);
  },

  deleteMeal: (mealId) => {
    const meals = db.getMeals().filter(m => m.id !== mealId);
    db.saveMeals(meals);
  },

  // User Profile
  getProfile: () => {
    const data = localStorage.getItem(DB_KEYS.PROFILE);
    return data ? JSON.parse(data) : null;
  },

  saveProfile: (profile) => {
    localStorage.setItem(DB_KEYS.PROFILE, JSON.stringify(profile));
  },

  // Weight History
  getWeights: () => {
    const data = localStorage.getItem(DB_KEYS.WEIGHTS);
    return data ? JSON.parse(data) : [];
  },

  saveWeights: (weights) => {
    localStorage.setItem(DB_KEYS.WEIGHTS, JSON.stringify(weights));
  },

  addWeight: (weight) => {
    const weights = db.getWeights();
    weights.push({ id: Date.now().toString(), ...weight, date: new Date().toISOString().split('T')[0] });
    db.saveWeights(weights);
    return weights;
  },

  // Workouts
  getWorkouts: () => {
    const data = localStorage.getItem(DB_KEYS.WORKOUTS);
    return data ? JSON.parse(data) : [];
  },

  saveWorkouts: (workouts) => {
    localStorage.setItem(DB_KEYS.WORKOUTS, JSON.stringify(workouts));
  },

  addWorkout: (workout) => {
    const workouts = db.getWorkouts();
    const newWorkout = {
      id: Date.now().toString(),
      ...workout,
      createdAt: new Date().toISOString(),
    };
    workouts.push(newWorkout);
    db.saveWorkouts(workouts);
    return newWorkout;
  },

  getWorkoutsByDate: (dateStr) => {
    const workouts = db.getWorkouts();
    return workouts.filter(w => w.date === dateStr);
  },
};

// Nutrition Calculator Utilities

/**
 * Calculate BMR using Mifflin-St Jeor equation
 * @param {number} weight - weight in kg
 * @param {number} height - height in cm
 * @param {number} age - age in years
 * @param {string} sex - 'male' or 'female'
 */
export const calculateBMR = (weight, height, age, sex) => {
  if (sex === 'male') {
    return 10 * weight + 6.25 * height - 5 * age + 5;
  }
  return 10 * weight + 6.25 * height - 5 * age - 161;
};

/**
 * Calculate daily calorie needs based on activity level
 */
export const calculateTDEE = (bmr, activityLevel) => {
  const multipliers = {
    sedentary: 1.2,
    light: 1.375,
    moderate: 1.55,
    active: 1.725,
    veryActive: 1.9,
  };
  return Math.round(bmr * (multipliers[activityLevel] || 1.2));
};

/**
 * Calculate target calories based on goal
 */
export const calculateTargetCalories = (tdee, goal) => {
  switch (goal) {
    case 'loss':
      return Math.round(tdee * 0.8); // 20% deficit
    case 'gain':
      return Math.round(tdee * 1.15); // 15% surplus
    case 'maintain':
    default:
      return tdee;
  }
};

/**
 * Calculate macronutrient targets based on calorie goal and preference
 */
export const calculateMacros = (calories, goal, activityLevel) => {
  let proteinRatio, fatRatio, carbRatio;

  switch (goal) {
    case 'loss':
      proteinRatio = 0.3; fatRatio = 0.35; carbRatio = 0.35;
      break;
    case 'gain':
      proteinRatio = 0.25; fatRatio = 0.25; carbRatio = 0.50;
      break;
    case 'maintain':
    default:
      proteinRatio = 0.25; fatRatio = 0.30; carbRatio = 0.45;
  }

  return {
    protein: Math.round((calories * proteinRatio) / 4), // 4 cal per gram protein
    fat: Math.round((calories * fatRatio) / 9), // 9 cal per gram fat
    carbs: Math.round((calories * carbRatio) / 4), // 4 cal per gram carbs
  };
};

/**
 * Calculate workout calories burned
 */
export const calculateWorkoutCalories = (activityType, durationMinutes, weightKg) => {
  // MET values for different activities
  const metValues = {
    running: 9.8,
    walking: 3.8,
    cycling: 7.5,
    swimming: 8.0,
    strength: 6.0,
    yoga: 3.0,
    hiit: 11.0,
    stretching: 2.5,
  };

  const met = metValues[activityType] || 5.0;
  // Calories = MET × weight(kg) × duration(hours)
  const hours = durationMinutes / 60;
  return Math.round(met * weightKg * hours);
};

/**
 * Format calories display
 */
export const formatCalories = (cal) => {
  return cal.toLocaleString('ru-RU');
};

/**
 * Calculate percentage of goal
 */
export const calcPercentage = (current, target) => {
  if (!target || target === 0) return 0;
  return Math.min(Math.round((current / target) * 100), 200);
};

/**
 * Get today's date string in YYYY-MM-DD format
 */
export const getTodayString = () => new Date().toISOString().split('T')[0];

/**
 * Format date for display
 */
export const formatDate = (dateStr) => {
  const date = new Date(dateStr);
  return date.toLocaleDateString('ru-RU', { day: 'numeric', month: 'short' });
};

/**
 * Get week day name
 */
export const getDayName = (dateStr) => {
  const date = new Date(dateStr);
  return date.toLocaleDateString('ru-RU', { weekday: 'short' });
};

