#!/usr/bin/env python3
"""
Bitrix24 Task Integration
Usage:
  python bitrix_tasks.py list                    # показать все задачи
  python bitrix_tasks.py list --status=2         # только активные (2)
  python bitrix_tasks.py create "Название"       # создать задачу
  python bitrix_tasks.py get 123                 # показать задачу 123
"""

import requests
import json
import sys

BASE_URL = "https://b24-1ank9k.bitrix24.ru/rest/1/tcraj448hshtalwq"

def api(method, params=None):
    url = f"{BASE_URL}/{method}.json"
    r = requests.post(url, json=params or {})
    return r.json()

def list_tasks(status=None):
    params = {"PARAMS": {"ORDER": {"ID": "DESC"}, "LIMIT": 50}}
    if status:
        params["PARAMS"]["FILTER"]["STATUS"] = status
    result = api("tasks.task.list", params)
    tasks = result.get("result", {}).get("tasks", [])
    return tasks

def create_task(title, description="", responsible_id=1):
    data = {
        "fields": {
            "TITLE": title,
            "DESCRIPTION": description,
            "RESPONSIBLE_ID": responsible_id,
            "CREATED_BY": 1
        }
    }
    result = api("tasks.task.add", data)
    return result

def get_task(task_id):
    result = api("tasks.task.get", {"taskId": task_id})
    return result.get("result", {})

def format_task(t):
    status_map = {"2": "🔄 В работе", "5": "✅ Готово", "1": "⏳ Новая"}
    status = status_map.get(str(t.get("status", "")), "❓ Неизвестно")
    title = t.get("title", "Без названия")
    rid = t.get("responsibleId", "?")
    tid = t.get("id", "?")
    return f"#{tid} [{status}] {title}\n   ↳ Отв: {rid}"

if __name__ == "__main__":
    cmd = sys.argv[1] if len(sys.argv) > 1 else "list"

    if cmd == "list":
        status = sys.argv[2] if len(sys.argv) > 2 and sys.argv[2].startswith("--status=") else None
        if status:
            status = status.split("=")[1]
        tasks = list_tasks(status)
        if not tasks:
            print("Нет задач")
        else:
            for t in tasks[:20]:
                print(format_task(t))

    elif cmd == "create":
        title = sys.argv[2] if len(sys.argv) > 2 else "Новая задача"
        desc = sys.argv[3] if len(sys.argv) > 3 else ""
        r = create_task(title, desc)
        if "result" in r:
            print(f"✅ Создана задача #{r['result']['task']['id']}: {title}")
        else:
            print(f"❌ Ошибка: {r}")

    elif cmd == "get":
        if len(sys.argv) < 3:
            print("Использование: python bitrix_tasks.py get <id>")
        else:
            t = get_task(sys.argv[2])
            print(json.dumps(t, indent=2, ensure_ascii=False))

    else:
        print(__doc__)

import { useState, useEffect } from 'react';
import { getProducts, searchProducts, getMealTypeName, calculateCalories } from '../utils/db';
import { DEFAULT_PRODUCTS } from '../data/defaultData';

export default function SearchScreen({ onBack }) {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const [recentProducts, setRecentProducts] = useState([]);
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [mealType, setMealType] = useState('breakfast');

  useEffect(() => {
    // Загружаем последние добавленные продукты
    const products = getProducts();
    const recent = products.slice(0, 10);
    setRecentProducts(recent);
    setResults(DEFAULT_PRODUCTS.slice(0, 20));
  }, []);

  const handleSearch = (text) => {
    setQuery(text);
    if (text.length < 1) {
      setResults(DEFAULT_PRODUCTS.slice(0, 20));
      return;
    }

    const allProducts = [...DEFAULT_PRODUCTS, ...getProducts()];
    const filtered = allProducts.filter(p => 
      p.name.toLowerCase().includes(text.toLowerCase()) ||
      p.category.toLowerCase().includes(text.toLowerCase())
    );
    setResults(filtered.slice(0, 30));
  };

  const handleSelectProduct = (product) => {
    setSelectedProduct(product);
  };

  const handleAddToMeal = (product, amount = 100) => {
    const db = getProducts();
    const mealKey = `meal_${mealType}`;
    const meals = JSON.parse(localStorage.getItem(mealKey) || '[]');

    const entry = {
      id: Date.now(),
      productId: product.id || product.name,
      name: product.name,
      amount,
      calories: Math.round((calculateCalories(product) * amount) / 100),
      protein: Math.round((product.protein * amount) / 100 * 10) / 10,
      fat: Math.round((product.fat * amount) / 100 * 10) / 10,
      carbs: Math.round((product.carbs * amount) / 100 * 10) / 10,
      mealType,
      time: new Date().toISOString()
    };

    meals.push(entry);
    localStorage.setItem(mealKey, JSON.stringify(meals));

    setSelectedProduct(null);
    setQuery('');
  };

  const mealTypes = [
    { id: 'breakfast', name: 'Завтрак', emoji: '🌅' },
    { id: 'lunch', name: 'Обед', emoji: '☀️' },
    { id: 'dinner', name: 'Ужин', emoji: '🌙' },
    { id: 'snack', name: 'Перекус', emoji: '🍎' }
  ];

  return (
    <div className="screen search-screen">
      <div className="screen-header">
        <button className="back-btn" onClick={onBack}>←</button>
        <h2>🔍 Поиск продуктов</h2>
      </div>

      <div className="search-box">
        <input
          type="text"
          placeholder="Введите название продукта..."
          value={query}
          onChange={(e) => handleSearch(e.target.value)}
          autoFocus
        />
      </div>

      <div className="meal-type-selector">
        <span>Приём пищи:</span>
        <div className="meal-types">
          {mealTypes.map(mt => (
            <button
              key={mt.id}
              className={`meal-type-btn ${mealType === mt.id ? 'active' : ''}`}
              onClick={() => setMealType(mt.id)}
            >
              {mt.emoji} {mt.name}
            </button>
          ))}
        </div>
      </div>

      {selectedProduct ? (
        <div className="product-detail">
          <div className="product-detail-header">
            <h3>{selectedProduct.name}</h3>
            <button onClick={() => setSelectedProduct(null)}>×</button>
          </div>

          <div className="product-macros">
            <div className="macro-item">
              <span className="macro-label">Калории</span>
              <span className="macro-value">{selectedProduct.calories} ккал</span>
            </div>
            <div className="macro-item">
              <span className="macro-label">Белки</span>
              <span className="macro-value">{selectedProduct.protein} г</span>
            </div>
            <div className="macro-item">
              <span className="macro-label">Жиры</span>
              <span className="macro-value">{selectedProduct.fat} г</span>
            </div>
            <div className="macro-item">
              <span className="macro-label">Углеводы</span>
              <span className="macro-value">{selectedProduct.carbs} г</span>
            </div>
          </div>

          <div className="amount-selector">
            <label>Количество (г):</label>
            <div className="amount-buttons">
              <button onClick={() => handleAddToMeal(selectedProduct, 50)}>50 г</button>
              <button onClick={() => handleAddToMeal(selectedProduct, 100)}>100 г</button>
              <button onClick={() => handleAddToMeal(selectedProduct, 150)}>150 г</button>
              <button onClick={() => handleAddToMeal(selectedProduct, 200)}>200 г</button>
            </div>
          </div>

          <button className="add-btn" onClick={() => handleAddToMeal(selectedProduct, 100)}>
            ✅ Добавить в {getMealTypeName(mealType)}
          </button>
        </div>
      ) : (
        <div className="search-results">
          <div className="results-section">
            <h4>📋 Результаты поиска ({results.length})</h4>
            {results.length === 0 && query.length > 0 && (
              <p className="no-results">Ничего не найдено</p>
            )}
            {results.map((product, idx) => (
              <div key={idx} className="product-item" onClick={() => handleSelectProduct(product)}>
                <div className="product-info">
                  <span className="product-name">{product.name}</span>
                  <span className="product-category">{product.category}</span>
                </div>
                <div className="product-calories">
                  <span>{product.calories} ккал</span>
                  <span className="per-100">/ 100 г</span>
                </div>
              </div>
            ))}
          </div>

          {query.length === 0 && recentProducts.length > 0 && (
            <div className="results-section">
              <h4>🕐 Недавно добавленные</h4>
              {recentProducts.slice(0, 5).map((product, idx) => (
                <div key={idx} className="product-item" onClick={() => handleSelectProduct(product)}>
                  <div className="product-info">
                    <span className="product-name">{product.name}</span>
                    <span className="product-category">свой продукт</span>
                  </div>
                  <div className="product-calories">
                    <span>{product.calories} ккал</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { Search as SearchIcon, Plus } from 'lucide-react';
import { db } from '../utils/db';
import { DEFAULT_PRODUCTS } from '../data/defaultData';

export default function SearchScreen() {
  const navigate = useNavigate();
  const [query, setQuery] = useState('');
  const [results, setResults] = useState(DEFAULT_PRODUCTS.slice(0, 20));
  const [selectedProduct, setSelectedProduct] = useState(null);
  const [mealType, setMealType] = useState('breakfast');
  const [amount, setAmount] = useState(100);

  const mealTypes = [
    { id: 'breakfast', name: 'Завтрак', emoji: '🌅' },
    { id: 'lunch', name: 'Обед', emoji: '☀️' },
    { id: 'dinner', name: 'Ужин', emoji: '🌙' },
    { id: 'snack', name: 'Перекус', emoji: '🍎' }
  ];

  const handleSearch = (text) => {
    setQuery(text);
    if (text.length < 1) {
      setResults(DEFAULT_PRODUCTS.slice(0, 20));
      return;
    }

    const allProducts = [...DEFAULT_PRODUCTS, ...db.getProducts()];
    const filtered = allProducts.filter(p => 
      p.name.toLowerCase().includes(text.toLowerCase()) ||
      p.category?.toLowerCase().includes(text.toLowerCase())
    );
    setResults(filtered.slice(0, 30));
  };

  const handleSelectProduct = (product) => {
    setSelectedProduct(product);
    setAmount(100);
  };

  const handleAddToMeal = () => {
    if (!selectedProduct) return;

    const entry = {
      id: Date.now().toString(),
      name: selectedProduct.name,
      calories: Math.round((selectedProduct.calories * amount) / 100),
      protein: Math.round((selectedProduct.protein * amount) / 100 * 10) / 10,
      fat: Math.round((selectedProduct.fat * amount) / 100 * 10) / 10,
      carbs: Math.round((selectedProduct.carbs * amount) / 100 * 10) / 10,
      date: new Date().toISOString().split('T')[0],
      mealType
    };

    db.addMeal(entry);
    setSelectedProduct(null);
    setQuery('');
    navigate('/');
  };

  const calcCalories = (p) => Math.round((p.calories * amount) / 100);

  return (
    <div className="screen">
      <header className="header">
        <button className="icon-btn" onClick={() => navigate('/')}>←</button>
        <h1>🔍 Поиск</h1>
      </header>

      <div className="search-bar">
        <SearchIcon size={20} />
        <input 
          type="text" 
          placeholder="Введите название..." 
          value={query}
          onChange={e => handleSearch(e.target.value)}
          autoFocus
        />
      </div>

      {selectedProduct ? (
        <div className="product-detail">
          <h3>{selectedProduct.name}</h3>
          <div className="product-macros-row" style={{marginBottom: '16px'}}>
            <span className="macro-tag protein">Б: {selectedProduct.protein}г</span>
            <span className="macro-tag fat">Ж: {selectedProduct.fat}г</span>
            <span className="macro-tag carbs">У: {selectedProduct.carbs}г</span>
          </div>

          <div style={{marginBottom: '16px'}}>
            <label>Количество: {amount}г</label>
            <input 
              type="range" 
              min="50" 
              max="500" 
              step="10"
              value={amount}
              onChange={e => setAmount(Number(e.target.value))}
              style={{width: '100%'}}
            />
            <div className="amount-buttons" style={{display: 'flex', gap: '8px', marginTop: '8px'}}>
              {[50, 100, 150, 200, 300].map(v => (
                <button key={v} onClick={() => setAmount(v)} style={{flex: 1}}>{v}г</button>
              ))}
            </div>
          </div>

          <div style={{marginBottom: '16px', fontSize: '24px', fontWeight: 'bold'}}>
            {calcCalories(selectedProduct)} ккал
          </div>

          <div className="meal-type-selector" style={{marginBottom: '16px'}}>
            <span>Приём пищи:</span>
            <div className="meal-types">
              {mealTypes.map(mt => (
                <button
                  key={mt.id}
                  className={`meal-type-btn ${mealType === mt.id ? 'active' : ''}`}
                  onClick={() => setMealType(mt.id)}
                >
                  {mt.emoji}
                </button>
              ))}
            </div>
          </div>

          <button className="btn-primary" onClick={handleAddToMeal}>
            ✅ Добавить
          </button>
        </div>
      ) : (
        <div className="products-list">
          {results.map((p, idx) => (
            <div key={idx} className="product-card" onClick={() => handleSelectProduct(p)}>
              <div className="product-header">
                <span className="product-name">{p.name}</span>
                <span className="product-calories-big">{p.calories} ккал</span>
              </div>
              <div className="product-macros-row">
                <span className="macro-tag protein">Б: {p.protein}г</span>
                <span className="macro-tag fat">Ж: {p.fat}г</span>
                <span className="macro-tag carbs">У: {p.carbs}г</span>
              </div>
            </div>
          ))}

          {query && results.length === 0 && (
            <div className="empty-state">
              <p>Не найдено</p>
              <button className="btn-secondary" onClick={() => navigate('/add-product')}>
                <Plus size={18} /> Добавить свой продукт
              </button>
            </div>
          )}
        </div>
      )}

      <nav className="nav">
        <button onClick={() => navigate('/')} className="nav-item"><span>Журнал</span></button>
        <button onClick={() => navigate('/search')} className="nav-item active"><span>Поиск</span></button>
        <button onClick={() => navigate('/stats')} className="nav-item"><span>Стата</span></button>
        <button onClick={() => navigate('/profile')} className="nav-item"><span>Профиль</span></button>
      </nav>
    </div>
  );
}

