// robot_arm_new.scad
// Простая 3D-печатная модель промышленного роботизированного манипулятора
// Под сервоприводы MG996R или SG90, материал: PLA
// Все отдельные детали рассчитаны так, чтобы помещаться на стол 200x200 мм.
// Авторежим по умолчанию показывает раскладку деталей для печати.

$fn = 64;

// ===================== НАСТРОЙКИ =====================
servo_type = "MG996R";     // "MG996R" или "SG90"
view_mode  = "print";      // "print" = детали на столе, "assembled" = собранный вид

// Основные размеры манипулятора
base_diameter = 90;
base_height   = 14;
lower_arm_len = 118;
upper_arm_len = 98;
arm_width     = 28;
arm_thick     = 12;
wall          = 4;
hole_d        = 5.2;       // отверстия под винт M5 / ось
clearance     = 0.5;       // технологический зазор для PLA

// Размеры популярных сервоприводов
function servo_body(t) =
    t == "SG90" ? [23.0, 12.2, 24.5] :   // корпус SG90: X,Y,Z
                  [40.7, 20.2, 39.5];    // корпус MG996R: X,Y,Z

function servo_tabs(t) =
    t == "SG90" ? [32.0, 12.2, 2.5] :    // уши крепления SG90
                  [54.5, 20.2, 2.8];     // уши крепления MG996R

servo = servo_body(servo_type);
tabs  = servo_tabs(servo_type);

// ===================== ВСПОМОГАТЕЛЬНЫЕ МОДУЛИ =====================

// Скругленный прямоугольный брусок, удобный для печати из PLA
module rounded_box(size=[20,20,5], r=3, center=true) {
    x = size[0]; y = size[1]; z = size[2];
    translate(center ? [0,0,0] : [x/2,y/2,z/2])
    hull() {
        for (sx=[-1,1], sy=[-1,1])
            translate([sx*(x/2-r), sy*(y/2-r), 0])
                cylinder(h=z, r=r, center=true);
    }
}

// Отверстие под ось/винт
module axle_hole(depth=80, d=hole_d) {
    rotate([90,0,0]) cylinder(h=depth, d=d, center=true);
}

// Прямоугольное посадочное окно под сервопривод
module servo_cutout(t=servo_type, extra=clearance) {
    s = servo_body(t);
    translate([0,0,0])
        cube([s[0]+extra, s[1]+extra, s[2]+extra], center=true);
}

// Отверстия под уши сервопривода
module servo_mount_holes(t=servo_type) {
    tb = servo_tabs(t);
    spacing = t == "SG90" ? 27.5 : 49.5;
    for (x=[-spacing/2, spacing/2])
        translate([x,0,0])
            cylinder(h=30, d=2.4, center=true);
}

// Рельефные ребра жесткости для индустриального вида
module rib(length=80, width=4, height=5) {
    rounded_box([length, width, height], r=1.5, center=true);
}

// ===================== ДЕТАЛИ =====================

// 1. База: круглая платформа с поворотным сервоприводом внутри
module base_part() {
    // База напоминает поворотный стол промышленного робота
    difference() {
        union() {
            cylinder(h=base_height, d=base_diameter, center=false);
            translate([0,0,base_height])
                cylinder(h=8, d=54, center=false);
            // декоративные ребра на основании
            for (a=[0:60:300])
                rotate([0,0,a])
                    translate([27,0,base_height+4])
                        rounded_box([30,6,8], r=2, center=true);
        }
        // облегчение снизу
        translate([0,0,-1]) cylinder(h=base_height-4, d=base_diameter-16, center=false);
        // центральное отверстие под вал/проводку
        translate([0,0,-1]) cylinder(h=base_height+20, d=12, center=false);
        // отверстия для крепления базы к поверхности
        for (a=[45,135,225,315])
            rotate([0,0,a]) translate([32,0,-1]) cylinder(h=base_height+4, d=4.2, center=false);
    }
}

// 2. Плечевой кронштейн: держит нижнее звено и сервопривод плеча
module shoulder_bracket_part() {
    // П-образная стойка, похожая на шарнир промышленного манипулятора
    s = servo_body(servo_type);
    bracket_w = max(62, tabs[0] + 10);
    bracket_h = s[2] + 24;
    bracket_d = s[1] + 18;

    difference() {
        union() {
            rounded_box([bracket_w, bracket_d, 8], r=4, center=true);
            translate([-bracket_w/2+6,0,bracket_h/2])
                rounded_box([12, bracket_d, bracket_h], r=4, center=true);
            translate([ bracket_w/2-6,0,bracket_h/2])
                rounded_box([12, bracket_d, bracket_h], r=4, center=true);
            translate([0,0,bracket_h+2])
                rounded_box([bracket_w, bracket_d, 8], r=4, center=true);
        }
        // посадочное окно под MG996R/SG90
        translate([0,0,bracket_h/2]) servo_cutout(servo_type, clearance);
        // отверстия крепления сервопривода
        translate([0,0,bracket_h/2 + s[2]/2]) servo_mount_holes(servo_type);
        // ось шарнира плеча
        translate([0,0,bracket_h]) axle_hole(depth=bracket_d+8, d=hole_d);
    }
}

// 3. Нижняя тяга: усиленное звено с облегчением и ребрами
module lower_arm_part() {
    // Длинное звено с двумя проушинами, как у настоящего промышленного робота
    difference() {
        union() {
            // две боковые пластины
            translate([0,-arm_width/2,0]) rounded_box([lower_arm_len, wall, arm_thick], r=3, center=true);
            translate([0, arm_width/2,0]) rounded_box([lower_arm_len, wall, arm_thick], r=3, center=true);
            // круговые бобышки вокруг шарниров
            for (x=[-lower_arm_len/2+12, lower_arm_len/2-12]) {
                translate([x,0,0]) cylinder(h=arm_thick, d=30, center=true);
                translate([x,0,0]) rounded_box([18, arm_width+8, arm_thick], r=4, center=true);
            }
            // диагональные ребра фермы
            translate([0,0,arm_thick/2+2]) rotate([0,0,10]) rib(lower_arm_len-36, 4, 4);
            translate([0,0,arm_thick/2+2]) rotate([0,0,-10]) rib(lower_arm_len-36, 4, 4);
        }
        // отверстия под оси шарниров
        for (x=[-lower_arm_len/2+12, lower_arm_len/2-12])
            translate([x,0,0]) cylinder(h=arm_thick+4, d=hole_d, center=true);
        // центральное облегчение
        rounded_box([lower_arm_len-52, arm_width-10, arm_thick+4], r=8, center=true);
    }
}

// 4. Локтевой кронштейн: переход между нижним и верхним звеном
module elbow_bracket_part() {
    // Компактный шарнир с местом под сервопривод локтя
    s = servo_body(servo_type);
    w = max(58, tabs[0] + 8);
    d = s[1] + 16;
    h = s[2] + 14;

    difference() {
        union() {
            rounded_box([w,d,10], r=4, center=true);
            translate([0,0,h/2]) rounded_box([w,d,h], r=5, center=true);
            translate([-w/2+8,0,h+8]) rounded_box([14,d,18], r=4, center=true);
            translate([ w/2-8,0,h+8]) rounded_box([14,d,18], r=4, center=true);
        }
        translate([0,0,h/2]) servo_cutout(servo_type, clearance);
        translate([0,0,h]) axle_hole(depth=d+10, d=hole_d);
        translate([0,0,h/2 + s[2]/2]) servo_mount_holes(servo_type);
    }
}

// 5. Верхняя тяга: более короткое звено для запястья
module upper_arm_part() {
    // Верхнее звено легче нижнего, но с тем же промышленным языком формы
    difference() {
        union() {
            translate([0,-arm_width/2,0]) rounded_box([upper_arm_len, wall, arm_thick], r=3, center=true);
            translate([0, arm_width/2,0]) rounded_box([upper_arm_len, wall, arm_thick], r=3, center=true);
            for (x=[-upper_arm_len/2+12, upper_arm_len/2-12]) {
                translate([x,0,0]) cylinder(h=arm_thick, d=28, center=true);
                translate([x,0,0]) rounded_box([16, arm_width+6, arm_thick], r=4, center=true);
            }
            translate([0,0,arm_thick/2+2]) rotate([0,0,12]) rib(upper_arm_len-34, 4, 4);
            translate([0,0,arm_thick/2+2]) rotate([0,0,-12]) rib(upper_arm_len-34, 4, 4);
        }
        for (x=[-upper_arm_len/2+12, upper_arm_len/2-12])
            translate([x,0,0]) cylinder(h=arm_thick+4, d=hole_d, center=true);
        rounded_box([upper_arm_len-48, arm_width-10, arm_thick+4], r=7, center=true);
    }
}

// 6. Запястье: маленький кронштейн перед захватом
module wrist_part() {
    // Узел запястья связывает верхнюю тягу и простой захват
    difference() {
        union() {
            rounded_box([46,34,12], r=4, center=true);
            translate([0,0

// robot_arm_v4.scad
// Оптимизированная роботизированная рука под 28BYJ-48 + ULN2003
// Единицы: миллиметры. Концепция: лёгкие рычаги, жёсткие коробчатые профили,
// низкий центр масс, прямой привод в суставах и параллелограмм ориентации инструмента.

$fn = 72;

// ------------------------- ПАРАМЕТРЫ -------------------------
// Геометрия двигателя 28BYJ-48
motor_d        = 28;
motor_h        = 19;
shaft_d        = 5;
shaft_l        = 10;
motor_hole_sp  = 35;
motor_ear_d    = 8;

// Плата драйвера ULN2003
board_x = 32;
board_y = 20;
board_z = 2;
board_holes_x = 23;
board_holes_y = 15;

// Рабочая кинематика: высота инструмента ~160 мм от стола.
// При установке на подставку/стол 140-220 мм рабочая зона попадает в 300-400 мм.
base_d = 70;
base_h = 50;
shoulder_z = 86;
lower_len = 108;
upper_len = 78;
lower_ang = 30;   // нижнее звено вверх: меньше момент на плече
upper_ang = -18;  // верхнее звено слегка вниз: рабочая зона PCB/пайка

// Печатные структурные ограничения
wall = 3;         // минимальная стенка 3 мм
arm_w = 18;       // ширина рычага по Y
arm_h = 16;       // высота рычага по Z/локальной оси
rib_t = 3;        // внутренние рёбра 3 мм
joint_d = 34;
link_d = 5;
link_offset_y = 17;

// Расчётные точки в плоскости XZ
shoulder = [0, 0, shoulder_z];
elbow_x  = lower_len * cos(lower_ang);
elbow_z  = shoulder_z + lower_len * sin(lower_ang);
wrist_x  = elbow_x + upper_len * cos(lower_ang + upper_ang);
wrist_z  = elbow_z + upper_len * sin(lower_ang + upper_ang);

// ------------------------- СЛУЖЕБНЫЕ МОДУЛИ -------------------------
module rounded_box(size=[10,10,10], r=2, center=true) {
    // Лёгкое скругление через minkowski; используется умеренно, чтобы файл рендерился быстро.
    minkowski() {
        cube([size[0]-2*r, size[1]-2*r, size[2]-2*r], center=center);
        sphere(r=r, $fn=24);
    }
}

module bolt_hole(d=3.2, h=12) {
    cylinder(d=d, h=h, center=true, $fn=32);
}

module screw_head(d=7, h=2) {
    color("#222222") cylinder(d=d, h=h, center=true, $fn=32);
}

module bearing_ring(od=26, id=12, h=8) {
    // Кольцо под втулку/подшипник: распределяет нагрузку и снижает изгиб оси.
    color("#b8bcc2")
    difference() {
        cylinder(d=od, h=h, center=true);
        cylinder(d=id, h=h+0.4, center=true);
    }
}

// ------------------------- КОМПОНЕНТЫ -------------------------
module motor_28byj(label="28BYJ-48") {
    // Модель двигателя: цилиндрический корпус, монтажные уши 35 мм, вал 5 мм.
    color("#c7cbd1")
    union() {
        cylinder(d=motor_d, h=motor_h, center=true);
        hull() {
            translate([-motor_hole_sp/2, 0, 0]) cylinder(d=motor_ear_d, h=3, center=true);
            translate([ motor_hole_sp/2, 0, 0]) cylinder(d=motor_ear_d, h=3, center=true);
        }
    }
    color("#202327")
    for (x=[-motor_hole_sp/2, motor_hole_sp/2])
        translate([x,0,0]) cylinder(d=3.2, h=4, center=true);

    color("#e1e4e8")
    translate([0,0,motor_h/2 + shaft_l/2]) cylinder(d=shaft_d, h=shaft_l, center=true);

    color("#8d949e")
    translate([0, -motor_d/2-3, 0]) cube([17,5,11], center=true); // кабельный выступ

    // Небольшая метка направления, не влияет на печать.
    color("#4d5662")
    translate([0,0,motor_h/2+0.2]) linear_extrude(height=0.4)
        text(label, size=3.0, halign="center", valign="center");
}

module uln2003_board() {
    // Плата драйвера на базе: короткие провода, меньше паразитных моментов.
    color("#1f7a48") rounded_box([board_x, board_y, board_z], r=0.8, center=true);
    color("#d7d09a")
    for (x=[-board_holes_x/2, board_holes_x/2])
        for (y=[-board_holes_y/2, board_holes_y/2])
            translate([x,y,board_z/2+0.15]) cylinder(d=2.4, h=0.4, center=true, $fn=20);
    color("#151515") translate([-8,0,2.5]) cube([12,7,3], center=true);
    color("#284cff") for (i=[0:3]) translate([6+i*3.2,-6,2.7]) cube([2.2,4,3.4], center=true);
    color("#f1c232") translate([10,6,2.6]) cube([8,5,3.2], center=true);
}

module base_assembly() {
    // Тяжёлая широкая база: центр масс максимально низко, диаметр 70 мм, высота 50 мм.
    color("#6c737d")
    difference() {
        cylinder(d=base_d, h=base_h, center=false);
        // Карман снизу под утяжелитель/стальную шайбу; оставлена 4-мм стенка.
        translate([0,0,4]) cylinder(d=base_d-12, h=18, center=false);
        // Четыре крепёжных отверстия к столу или плите.
        for(a=[45,135,225,315])
            rotate([0,0,a]) translate([base_d/2-12,0,base_h-8]) cylinder(d=4.4, h=18, center=true);
    }

    color("#969da6")
    translate([0,0,base_h]) cylinder(d1=46, d2=34, h=22, center=false);

    // Низкое размещение электроники и противовеса.
    translate([0,-33,14]) rotate([90,0,0]) uln2003_board();
    color("#33383f") translate([0,25,12]) rounded_box([42,10,16], r=2, center=true); // противовес

    // Вилка плечевого узла с двумя щёками: нагрузка не висит консольно на валу.
    color("#8e969f")
    for(y=[-14,14])
        translate([0,y,shoulder_z]) rounded_box([44,wall,42], r=2, center=true);
    translate([0,0,shoulder_z]) bearing_ring(od=38, id=13, h=32);

    // Двигатель плеча расположен на базе/у основания: масса не переносится на локоть.
    translate([0,-29,shoulder_z]) rotate([90,0,0]) motor_28byj("SH");
}

module box_arm(L=100, name="arm") {
    // Коробчатый рычаг с внутренним окном и диагональными рёбрами.
    // Стенка/рёбра >= 3 мм, печатается без тонких слабых мест.
    color("#aeb4bb")
    difference() {
        rounded_box([L, arm_w, arm_h], r=2, center=true);
        rounded_box([L-2*wall-8, arm_w+0.8, arm_h-2*wall], r=1.2, center=true);
        // продольные окна для снижения инерции при сохранении жёсткости
        for(x=[-L/4, L/4])
            translate([x,0,0]) rounded_box([L/4, arm_w+1, arm_h-2*wall-2], r=1.2, center=true);
    }

    // Диагональные рёбра: Х-ферма против кручения.
    color("#8d949e")
    for(s=[-1,1])
        rotate([0,s*atan((arm_h-2*wall)/(L-18)),0])
            cube([L-18, rib_t, rib_t], center=true);

    // Верхняя/нижняя силовые полки.
    color("#c3c8cf")
    for(z=[-(arm_h/2-wall/2), arm_h/2-wall/2])
        translate([0,0,z]) cube([L-8, arm_w-2, wall], center=true);
}

module joint_hub(label="J") {
    // Большой фланец распределяет момент по рычагу, не перегружая вал 28BYJ.
    color("#a5abb3") cylinder(d=joint_d, h=arm_w+6, center=true, $fn=72);
    bearing_ring(od=26, id=8, h=arm_w+8);
    color("#222222")
    for(a=[0,90,180,270])
        rotate([0,0,a]) translate([joint_d/2-6,0,arm_w/2+3.2]) cylinder(d=3, h=1.4, center=true);
    color("#515965")
    translate([0,0,arm_w/2+4.2]) linear_extrude(height=0.4)
        text(label, size=5, halign="center", valign="center");
}

module lower_arm_assembly() {
    // Нижний рычаг длиннее: лёгкий короб + база-привод, минимум массы на конце.
    translate(shoulder)
    rotate([0,-lower_ang,0]) {
        translate([lower_len/2,0,0]) box_arm(lower_len, "lower");
        translate([0,0,0]) joint_hub("SH");
        translate([lower_len,0,0]) joint_hub("EL");

        // Контрбаланс рядом с плечом: уменьшает удерживающий момент двигателя.
        color("#3d4249") translate([-22,0,-10]) rounded_box([24,20,18], r=3, center=true);
    }
}

module upper_arm_assembly() {
    // Верхний рычаг короче и легче; мотор локтя допустим на локте.
