// -------------------------
// Вспомогательные модули
// -------------------------
module rounded_box(size=[10,10,10], r=2) {
    // Коробка со скругленными углами в XY, удобная для прочных печатных деталей
    hull() {
        for (x=[-size[0]/2+r, size[0]/2-r])
            for (y=[-size[1]/2+r, size[1]/2-r])
                translate([x,y,0]) cylinder(h=size[2], r=r, center=true);
    }
}

module mg996r_cutout(extra=0) {
    // Карман под корпус MG996R и его крепежные ушки
    union() {
        cube([servo_l + 2*extra, servo_w + 2*extra, servo_h + 2*extra], center=true);
        translate([0,0,servo_h/2 - servo_flange_t/2])
            cube([servo_flange_l + 2*extra, servo_flange_w + 2*extra, servo_flange_t + 2*extra], center=true);

        // Отверстия крепления ушек MG996R под M3
        for (x=[-24,24])
            translate([x,0,servo_h/2])
                cylinder(h=20, d=servo_screw_d + extra, center=true);
    }
}

module screw_holes_xy(xdist=24, ydist=24, d=3.2, h=20) {
    // Стандартная группа из четырех отверстий под винты
    for (x=[-xdist/2, xdist/2])
        for (y=[-ydist/2, ydist/2])
            translate([x,y,0]) cylinder(h=h, d=d, center=true);
}

module rib(length=70, height=18, thick=4) {
    // Треугольное ребро жесткости для индустриального вида и прочности
    rotate([90,0,0])
        linear_extrude(height=thick, center=true)
            polygon(points=[[0,0],[length,0],[0,height]]);
}

module circular_joint(outer_d=42, inner_d=pivot_d, h=plate_t) {
    // Круглый шарнирный фланец, похожий на промышленный узел
    difference() {
        cylinder(h=h, d=outer_d, center=true);
        cylinder(h=h+2, d=inner_d, center=true);
        for (a=[0:90:270])
            rotate([0,0,a]) translate([outer_d*0.32,0,0])
                cylinder(h=h+2, d=3.2, center=true);
    }
}

